// âm = [file] hoặc [file, giây đầu, giây cuối]; đoạn có am = file đọc cả đoạn. Đường dẫn tính từ thư mục bài.
window.BK_GIANG=[{"id":"tttc","zh":"预科汉语强化教程","vi":"Tiếng Trung tăng cường 1","bai":[{"n":1,"ten":"你好","doan":[{"t":"课文 1","c":[["李白","老师，您好！","Lǎoshī, nín hǎo!","Em chào thầy ạ!"],["李思齐","你好！你叫什么名字？","Nǐ hǎo! Nǐ jiào shénme míngzi?","Chào em! Em tên là gì?"],["李白","我叫李白。","Wǒ jiào Lǐ Bái.","Em tên là Lý Bạch."],["李思齐","你是哪国人？","Nǐ shì nǎ guó rén?","Em là người nước nào?"],["李白","我是法国人。","Wǒ shì fǎguórén.","Em là người Pháp."],["李思齐","请坐。","Qǐng zuò.","Mời em ngồi."],["李白","谢谢！","Xièxie!","Em cảm ơn thầy!"],["李思齐","不用谢！","Búyòng xiè!","Không có gì!"]]},{"t":"课文 2","c":[["李白","你好，你是学生吗？","Nǐ hǎo, nǐ shì xuésheng ma?","Chào bạn, bạn là sinh viên à?"],["王语","我不是学生，我是老师。","Wǒ bú shì xuésheng, wǒ shì lǎoshī.","Tôi không phải sinh viên, tôi là giáo viên."],["李白","对不起。","Duìbuqǐ.","Em xin lỗi ạ."],["王语","没关系。","Méi guānxi.","Không sao."],["李白","请问，您贵姓？","Qǐngwèn, nín guìxìng?","Cho em hỏi, cô họ gì ạ?"],["王语","我姓王，叫王语。你呢？","Wǒ xìng Wáng, jiào Wáng Yǔ. Nǐ ne?","Cô họ Vương, tên là Vương Ngữ. Còn em?"],["李白","我叫李白。","Wǒ jiào Lǐ Bái.","Em tên là Lý Bạch."],["王语","你是美国人吗？","Nǐ shì měiguórén ma?","Em là người Mỹ à?"],["李白","不是，我是法国人。","Bú shì, wǒ shì fǎguórén.","Không ạ, em là người Pháp."],["李白","王老师，再见！","Wáng lǎoshī, zàijiàn!","Em chào cô Vương ạ!"],["王语","再见，李白。","Zàijiàn, Lǐ Bái.","Tạm biệt em, Lý Bạch."]]}]},{"n":2,"ten":"这是你的手机吗","doan":[{"t":"课文 1","c":[["同学","早上好！李白，这是你的手机吗？","Zǎoshang hǎo! Lǐ Bái, zhè shì nǐ de shǒujī ma?","Chào buổi sáng! Lý Bạch, đây là điện thoại của cậu à?"],["李白","对，是我的手机。","Duì, shì wǒ de shǒujī.","Đúng, là điện thoại của mình."],["同学","是新手机吗？很好看。","Shì xīn shǒujī ma? Hěn hǎokàn.","Điện thoại mới à? Đẹp quá."],["李白","谢谢，是新手机。你也喜欢黑色的手机吗？","Xièxie, shì xīn shǒujī. Nǐ yě xǐhuan hēisè de shǒujī ma?","Cảm ơn, là điện thoại mới. Cậu cũng thích điện thoại màu đen à?"],["同学","对。那是谁的手机？","Duì. Nà shì shéi de shǒujī?","Ừ. Kia là điện thoại của ai thế?"],["李白","我也不知道。","Wǒ yě bù zhīdào.","Mình cũng không biết."]]},{"t":"课文 2","c":[["同学","晚上好！米雪，这些都是你的书吗？","Wǎnshang hǎo! Mǐ Xuě, zhèxiē dōu shì nǐ de shū ma?","Chào buổi tối! Mễ Tuyết, những cái này đều là sách của bạn à?"],["米雪","对，都是我的书。","Duì, dōu shì wǒ de shū.","Đúng, đều là sách của mình."],["同学","是英语书吗？","Shì Yīngyǔ shū ma?","Là sách tiếng Anh à?"],["米雪","不是，是汉语课本。","Bú shì, shì Hànyǔ kèběn.","Không phải, là giáo trình tiếng Hán."],["同学","你们的汉语课本难吗？","Nǐmen de Hànyǔ kèběn nán ma?","Giáo trình tiếng Hán của các bạn có khó không?"],["米雪","不难。","Bù nán.","Không khó."],["同学","那些也是你的书吗？","Nàxiē yě shì nǐ de shū ma?","Những cái kia cũng là sách của bạn à?"],["米雪","那些不是我的书。","Nàxiē bú shì wǒ de shū.","Những cái kia không phải sách của mình."],["同学","你的汉语很不错。","Nǐ de Hànyǔ hěn búcuò.","Tiếng Hán của bạn khá thật đấy."],["米雪","谢谢！","Xièxie!","Cảm ơn!"]]}]},{"n":3,"ten":"你家有几口人","doan":[{"t":"课文 1","c":[["马小军","这是你家的照片吗？","Zhè shì nǐ jiā de zhàopiàn ma?","Đây là ảnh gia đình cậu à?"],["李白","是。这是我爸爸，这是我妈妈。","Shì. Zhè shì wǒ bàba, zhè shì wǒ māma.","Ừ. Đây là bố mình, đây là mẹ mình."],["马小军","他是你弟弟吗？","Tā shì nǐ dìdi ma?","Cậu bé này là em trai cậu à?"],["李白","对，我有一个弟弟、一个妹妹。","Duì, wǒ yǒu yí ge dìdi, yí ge mèimei.","Đúng rồi, mình có một em trai, một em gái."],["马小军","你有哥哥、姐姐吗？","Nǐ yǒu gēge, jiějie ma?","Cậu có anh trai, chị gái không?"],["李白","没有。你家有几口人？","Méiyǒu. Nǐ jiā yǒu jǐ kǒu rén?","Không có. Nhà cậu có mấy người?"],["马小军","三口。","Sān kǒu.","Ba người."]]},{"t":"课文 2","c":[["米雪","早上好，马小军！","Zǎoshang hǎo, Mǎ Xiǎojūn!","Chào buổi sáng, Mã Tiểu Quân!"],["马小军","早啊，米雪！我介绍一下，这是我朋友张萌，她也是中国人，这是米雪。","Zǎo a, Mǐ Xuě! Wǒ jièshào yíxià, zhè shì wǒ péngyou Zhāng Méng, tā yě shì Zhōngguórén, zhè shì Mǐ Xuě.","Chào Michelle! Mình giới thiệu một chút, đây là bạn mình Trương Manh, cô ấy cũng là người Trung Quốc; đây là Michelle."],["米雪","你好！认识你很高兴。","Nǐ hǎo! Rènshi nǐ hěn gāoxìng.","Chào bạn! Rất vui được làm quen với bạn."],["张萌","认识你我也很高兴。","Rènshi nǐ wǒ yě hěn gāoxìng.","Mình cũng rất vui được làm quen với chị."],["米雪","你也是这个大学的学生吗？","Nǐ yě shì zhège dàxué de xuésheng ma?","Bạn cũng là sinh viên trường đại học này à?"],["张萌","对。我学习医学。这是你儿子吧？真可爱！","Duì. Wǒ xuéxí yīxué. Zhè shì nǐ érzi ba? Zhēn kě'ài!","Vâng. Mình học y. Đây là con trai chị phải không? Đáng yêu quá!"],["米雪","谢谢！","Xièxie!","Cảm ơn!"]]}]},{"n":4,"ten":"电影开始了吗","doan":[{"t":"课文 1","c":[["马小军","李白，你睡觉了吗？","Lǐ Bái, nǐ shuìjiào le ma?","Lý Bạch, cậu ngủ chưa?"],["李白","还没睡。","Hái méi shuì.","Vẫn chưa ngủ."],["马小军","你明天下午有课吗？","Nǐ míngtiān xiàwǔ yǒu kè ma?","Chiều mai cậu có tiết học không?"],["李白","有，我两点上课。","Yǒu, wǒ liǎng diǎn shàngkè.","Có, 2 giờ mình vào học."],["马小军","几点下课？","Jǐ diǎn xiàkè?","Mấy giờ tan học?"],["李白","三点四十分下课。","Sān diǎn sìshí fēn xiàkè.","3 giờ 40 tan học."],["马小军","明天下午我和朋友去看电影，你去吗？","Míngtiān xiàwǔ wǒ hé péngyou qù kàn diànyǐng, nǐ qù ma?","Chiều mai mình với bạn đi xem phim, cậu đi không?"],["李白","好，我也去。","Hǎo, wǒ yě qù.","Được, mình cũng đi."]]},{"t":"课文 2","c":[["李白","电影开始了吗？","Diànyǐng kāishǐ le ma?","Phim bắt đầu chưa?"],["马小军","还没开始，五点半开始。","Hái méi kāishǐ, wǔ diǎn bàn kāishǐ.","Chưa bắt đầu, 5 rưỡi mới bắt đầu."],["李白","现在几点？","Xiànzài jǐ diǎn?","Bây giờ mấy giờ rồi?"],["马小军","五点一刻，还有十五分钟。","Wǔ diǎn yí kè, hái yǒu shíwǔ fēnzhōng.","5 giờ 15, còn 15 phút nữa."],["李白","你们想喝咖啡吗？我去买。","Nǐmen xiǎng hē kāfēi ma? Wǒ qù mǎi.","Các cậu muốn uống cà phê không? Mình đi mua."],["马小军","好，谢谢！我去一下洗手间。","Hǎo, xièxie! Wǒ qù yíxià xǐshǒujiān.","Được, cảm ơn nhé! Mình đi vệ sinh một chút."]]}]},{"n":5,"ten":"办公楼在哪儿","doan":[{"t":"课文 1","c":[["外卖送餐员","您好，您在办公楼，是吗？","Nín hǎo, nín zài bàngōnglóu, shì ma?","Xin chào, bạn đang ở tòa nhà văn phòng, phải không?"],["王 语","对。","Duì.","Đúng."],["外卖送餐员","我在图书馆的南边，办公楼在哪儿？","Wǒ zài túshūguǎn de nánbian, bàngōnglóu zài nǎr?","Tôi đang ở phía nam thư viện, tòa nhà văn phòng ở đâu?"],["王 语","在图书馆的北边。","Zài túshūguǎn de běibian.","Ở phía bắc thư viện."],["外卖送餐员","好的。","Hǎo de.","Được rồi."],["外卖送餐员","您好，这是您的晚饭。","Nín hǎo, zhè shì nín de wǎnfàn.","Xin chào, đây là bữa tối của bạn."],["王 语","谢谢！","Xièxie!","Cảm ơn!"],["外卖送餐员","不客气。请问，留学生宿舍楼在哪儿？","Bú kèqi. Qǐngwèn, liúxuéshēng sùshèlóu zài nǎr?","Không có gì. Xin hỏi, tòa nhà ký túc xá du học sinh ở đâu?"],["王 语","在这个楼的前边。","Zài zhège lóu de qiánbian.","Ở phía trước tòa nhà này."]]},{"t":"课文 2","c":[["米 雪","周末没有课，你和马小军一起来我家玩儿吧。","Zhōumò méiyǒu kè, nǐ hé Mǎ Xiǎojūn yìqǐ lái wǒ jiā wánr ba.","Cuối tuần không có học, bạn và Mã Tiểu Quân cùng đến nhà mình chơi nhé."],["张 萌","好啊。你家在哪儿？离学校远吗？","Hǎo a. Nǐ jiā zài nǎr? Lí xuéxiào yuǎn ma?","Ừ được. Nhà bạn ở đâu? Có xa trường không?"],["米 雪","不远，在学校的东边，爱家花园。","Bù yuǎn, zài xuéxiào de dōngbian, Àijiā Huāyuán.","Không xa, ở phía đông trường, khu Ái Gia Hoa Viên."],["张 萌","几号楼？","Jǐ hào lóu?","Tòa nhà số mấy?"],["米 雪","七号楼六○一室。","Qī hào lóu liù líng yāo shì.","Tòa số 7 phòng 601."],["张 萌","我们星期天早上十点半去，好吗？","Wǒmen xīngqītiān zǎoshang shí diǎn bàn qù, hǎo ma?","Chúng mình đi Chủ nhật buổi sáng mười giờ rưỡi nhé?"],["米 雪","好，我在家等你们。","Hǎo, wǒ zài jiā děng nǐmen.","Được, mình ở nhà chờ các bạn."]]}]},{"n":6,"ten":"苹果多少钱一斤","doan":[{"t":"课文 1","c":[["丈 夫","冰箱里还有水果吗？","Bīngxiāng lǐ hái yǒu shuǐguǒ ma?","Trong tủ lạnh còn trái cây không?"],["王 语","还有一个苹果。我们去超市再买一点儿吧。","Hái yǒu yī gè píngguǒ. Wǒmen qù chāoshì zài mǎi yīdiǎnr ba.","Còn một quả táo. Chúng mình đến siêu thị mua thêm ít trái cây đi."],["丈 夫","好，去哪个超市？","Hǎo, qù nǎge chāoshì?","Được, đến siêu thị nào?"],["王 语","去大家乐吧，离家不远，卖的东西也不太贵。","Qù Dàjiālè ba, lí jiā bù yuǎn, mài de dōngxi yě bú tài guì.","Đến Đại Gia Lạc đi, không xa nhà, đồ bán cũng không quá đắt."],["丈 夫","好，再买两包牛奶。","Hǎo, zài mǎi liǎng bāo niúnǎi.","Được, mua thêm hai bịch sữa."],["王 语","那现在走吧，早上超市里人不多。","Nà xiànzài zǒu ba, zǎoshang chāoshì lǐ rén bù duō.","Vậy đi bây giờ đi, buổi sáng siêu thị ít người."]]},{"t":"课文 2","c":[["丈 夫","这儿的苹果真多，哪种好吃？","Zhèr de píngguǒ zhēn duō, nǎ zhǒng hǎochī?","Táo ở đây thật nhiều, loại nào ngon?"],["王 语","那种红的很甜。多少钱一斤？","Nà zhǒng hóng de hěn tián. Duōshao qián yī jīn?","Loại đỏ kia rất ngọt. Bao nhiêu tiền một cân?"],["丈 夫","我看一下，一斤十六块九。","Wǒ kàn yīxià, yī jīn shíliù kuài jiǔ.","Tôi xem thử, một cân mười sáu đồng chín."],["王 语","真贵！有便宜的吗？","Zhēn guì! Yǒu piányi de ma?","Đắt quá! Có loại rẻ không?"],["丈 夫","这种绿的便宜。","Zhè zhǒng lǜ de piányi.","Loại xanh này rẻ."],["王 语","多少钱？","Duōshao qián?","Bao nhiêu tiền?"],["丈 夫","七块九毛九一斤。","Qī kuài jiǔ máo jiǔ yī jīn.","Bảy đồng chín hào chín một cân."],["王 语","那买这种吧。","Nà mǎi zhè zhǒng ba.","Vậy mua loại này đi."]]}]},{"n":7,"ten":"你喜欢什么运动","doan":[{"t":"课文 1","c":[["米雪","周末你们一般做什么？","Zhōumò nǐmen yībān zuò shénme?","Cuối tuần các bạn thường làm gì?"],["张萌","我经常去图书馆学习。","Wǒ jīngcháng qù túshūguǎn xuéxí.","Tôi thường xuyên đến thư viện học."],["马小军","我有的时候在房间写写作业、看看电影，有的时候和朋友一起去旅游。","Wǒ yǒude shíhou zài fángjiān xiěxiě zuòyè, kànkan diànyǐng, yǒude shíhou hé péngyou yīqǐ qù lǚyóu.","Đôi khi tôi ở phòng viết bài tập, xem phim, đôi khi cùng bạn bè đi du lịch."],["米雪","我也很喜欢旅游。我买了很多本旅游的书。","Wǒ yě hěn xǐhuan lǚyóu. Wǒ mǎile hěn duō běn lǚyóu de shū.","Tôi cũng rất thích du lịch. Tôi đã mua rất nhiều quyển sách du lịch."],["张萌","小龙，你周末喜欢做什么？","Xiǎo Lóng, nǐ zhōumò xǐhuan zuò shénme?","Tiểu Long, cuối tuần cậu thích làm gì?"],["小龙","我喜欢去动物园！","Wǒ xǐhuan qù dòngwùyuán!","Tôi thích đi vườn thú!"]]},{"t":"课文 2","c":[["马小军","你现在去哪儿？教室还是图书馆？","Nǐ xiànzài qù nǎr? Jiàoshì háishi túshūguǎn?","Bây giờ bạn đi đâu? Lớp học hay thư viện?"],["张萌","我想去游泳馆游泳。我办了一张卡。","Wǒ xiǎng qù yóuyǒngguǎn yóuyǒng. Wǒ bànle yī zhāng kǎ.","Tôi muốn đến bể bơi bơi lội. Tôi đã làm một cái thẻ."],["马小军","你经常运动吗？","Nǐ jīngcháng yùndòng ma?","Bạn có thường xuyên tập thể dục không?"],["张萌","我每天都锻炼，跑跑步或者游游泳。","Wǒ měi tiān dōu duànliàn, pǎopao bù huòzhě yóuyou yǒng.","Tôi luyện tập mỗi ngày, chạy bộ một chút hoặc bơi một chút."],["马小军","我也有每天锻炼的习惯。","Wǒ yě yǒu měi tiān duànliàn de xíguàn.","Tôi cũng có thói quen luyện tập mỗi ngày."],["张萌","你喜欢什么运动？","Nǐ xǐhuan shénme yùndòng?","Bạn thích môn thể thao gì?"],["马小军","踢足球、打篮球、爬山，我都很喜欢。","Tī zúqiú, dǎ lánqiú, pá shān, wǒ dōu hěn xǐhuan.","Đá bóng, chơi bóng rổ, leo núi — tôi đều rất thích."]]}]}]},{"id":"301","zh":"汉语会话301句","vi":"301 câu đàm thoại","bai":[{"n":11,"ten":"我要买橘子","doan":[{"t":"课文 1","c":[["售货员","您要什么？","Nín yào shénme?","Ông/bà cần gì?"],["大卫","我要苹果。多少钱一斤？","Wǒ yào píngguǒ. Duōshao qián yì jīn?","Tôi cần táo. Bao nhiêu tiền một cân?"],["售货员","两块五（毛）。","Liǎng kuài wǔ (máo).","Hai đồng năm (hào)."],["大卫","那种呢？","Nà zhǒng ne?","Loại kia thì sao?"],["售货员","一块三。","Yì kuài sān.","Một đồng ba (hào)."],["大卫","要这种吧。","Yào zhè zhǒng ba.","Lấy loại này vậy."],["售货员","要多少？","Yào duōshao?","Cần bao nhiêu?"],["大卫","两斤。","Liǎng jīn.","Hai cân."],["售货员","还要别的吗？","Hái yào biéde ma?","Còn cần gì khác không?"],["大卫","不要了。","Bú yào le.","Không cần nữa."]]},{"t":"课文 2","c":[["售货员","您要买什么？","Nín yào mǎi shénme?","Ông/bà muốn mua gì?"],["玛丽","我要买橘子。一斤多少钱？","Wǒ yào mǎi júzi. Yì jīn duōshao qián?","Tôi muốn mua quýt. Một cân bao nhiêu tiền?"],["售货员","两块八。","Liǎng kuài bā.","Hai đồng tám."],["玛丽","太贵了。","Tài guì le.","Đắt quá."],["售货员","那种便宜。","Nà zhǒng piányi.","Loại kia rẻ."],["玛丽","那种好不好？","Nà zhǒng hǎo bu hǎo?","Loại đó có tốt không?"],["售货员","您尝尝。","Nín chángchang.","Mời ông/bà nếm thử."],["玛丽","好，我要四个。","Hǎo, wǒ yào sì ge.","Được, tôi lấy bốn quả."],["售货员","这是一斤半，三块七毛五分。还买别的吗？","Zhè shì yì jīn bàn, sān kuài qī máo wǔ fēn. Hái mǎi biéde ma?","Đây là một cân rưỡi, ba đồng bảy hào năm xu. Còn mua gì khác không?"],["玛丽","不要了。","Bú yào le.","Không cần nữa."]]}]},{"n":12,"ten":"我想买件毛衣","doan":[{"t":"课文 1","c":[["大卫","天冷了。我想買件毛衣。","Tiān lěng le. Wǒ xiǎng mǎi jiàn máoyī.","Trời lạnh rồi. Tôi muốn mua chiếc áo len."],["玛丽","我也要买东西。我们什么时候去？","Wǒ yě yào mǎi dōngxi. Wǒmen shénme shíhou qù?","Tôi cũng muốn mua đồ. Khi nào chúng ta đi?"],["大卫","星期天去，怎么样？","Xīngqītiān qù, zěnmeyàng?","Chủ nhật đi, thế nào?"],["玛丽","星期天人太多。","Xīngqītiān rén tài duō.","Chủ nhật đông người lắm."],["大卫","那明天下午去吧。","Nà míngtian xiàwǔ qù ba.","Vậy chiều mai đi nhé."]]},{"t":"课文 2","c":[["大卫","小姐，我看看那件毛衣。","Xiǎojie, wǒ kànkan nà jiàn máoyī.","Cô ơi, cho tôi xem chiếc áo len kia một lát."],["售货员","好。","Hǎo.","Dạ được ạ."],["大卫","我可以试试吗？","Wǒ kěyǐ shìshi ma?","Tôi có thể mặc thử không?"],["售货员","您试一下儿吧。","Nín shì yíxiàr ba.","Anh mặc thử một chút xem sao."],["玛丽","这件太短了。","Zhè jiàn tài duǎn le.","Chiếc này ngắn quá rồi."],["售货员","您试试那件。","Nín shìshi nà jiàn.","Anh thử chiếc kia xem."],["大卫","好，我再试一下儿。","Hǎo, wǒ zài shì yíxiàr.","Được, để tôi thử lại xem."],["玛丽","这件不大也不小。","Zhè jiàn bú dà yě bù xiǎo.","Chiếc này không to cũng không nhỏ (vừa vặn lắm)."],["大卫","好极了，我就买这件。","Hǎo jí le, wǒ jiù mǎi zhè jiàn.","Tốt quá rồi, tôi mua chiếc này vậy."]]}]},{"n":13,"ten":"要换车","doan":[{"t":"课文 1","c":[["玛丽","请问，这路车到天安门吗？","Qǐng wèn, zhè lù chē dào Tiān’ānmén ma?","Xin hỏi, tuyến xe này có đến Thiên An Môn không?"],["售票员","到。上车吧。","Dào. Shàng chē ba.","Có. Lên xe đi."],["大卫","买两张票。多少钱一张？","Mǎi liǎng zhāng piào. Duōshao qián yì zhāng?","Mua hai vé. Bao nhiêu tiền một vé?"],["售票员","五毛。","Wǔ máo.","Năm hào."],["大卫","给你两块钱。","Gěi nǐ liǎng kuài qián.","Gửi chị hai đồng."],["售票员","找你一块。","Zhǎo nǐ yí kuài.","Trả lại anh một đồng."],["玛丽","请问，到天安门还有几站？","Qǐng wèn, dào Tiān’ānmén hái yǒu jǐ zhàn?","Xin hỏi, đến Thiên An Môn còn mấy trạm nữa?"],["A","三站。你们会说汉语？","Sān zhàn. Nǐmen huì shuō Hànyǔ?","Ba trạm. Các bạn biết nói tiếng Hoa à?"],["大卫","会说一点儿。","Huì shuō yìdiǎnr.","Biết nói một chút."],["玛丽","我说汉语，你懂吗？","Wǒ shuō Hànyǔ, nǐ dǒng ma?","Tôi nói tiếng Hoa, anh hiểu không?"],["A","懂。你们是哪国人？","Dǒng. Nǐmen shì nǎ guó rén?","Hiểu. Các bạn là người nước nào?"],["大卫","我是法国人。","Wǒ shì Fǎguó rén.","Tôi là người Pháp."],["玛丽","我是美国人。","Wǒ shì Měiguó rén.","Tôi là người Mỹ."],["售票员","天安门到了。请下车吧。","Tiān’ānmén dào le. Qǐng xià chē ba.","Đến Thiên An Môn rồi. Mời xuống xe."]]},{"t":"课文 2","c":[["大卫","劳驾，我买一张票。","Láojià, wǒ mǎi yì zhāng piào.","Làm phiền, tôi mua một vé."],["售票员","哪儿上的？","Nǎr shàng de?","Lên xe ở đâu?"],["大卫","前一站。","Qián yí zhàn.","Trạm phía trước."],["售票员","去哪儿？","Qù nǎr?","Đi đâu?"],["大卫","去语言文化大学。要换车吗？","Qù Yǔyán Wénhuà Dàxué. Yào huàn chē ma?","Đến Đại học Ngôn ngữ Văn hóa. Có phải đổi tuyến xe không?"],["售票员","要换车。","Yào huàn chē.","Phải đổi tuyến xe."],["大卫","在哪儿换车？","Zài nǎr huàn chē?","Đổi tuyến xe ở đâu?"],["售票员","北京师范大学。","Běijīng Shīfàn Dàxué.","Đại học Sư phạm Bắc Kinh."],["大卫","换几路车？","Huàn jǐ lù chē?","Đổi tuyến xe số mấy?"],["售票员","换331路。","Huàn sānsānyāo lù.","Đổi tuyến 331."],["大卫","谢谢！","Xièxie!","Cảm ơn!"],["售票员","不谢。","Bú xiè.","Không có gì."]]}]},{"n":14,"ten":"我要去换钱","doan":[{"t":"课文 1","c":[["玛丽","钱都花了，我没钱了。我要去换钱。","Qián dōu huā le, wǒ méi qián le. Wǒ yào qù huàn qián.","Tiền tiêu hết rồi, tôi hết tiền rồi. Tôi phải đi đổi tiền."],["大卫","听说，饭店里可以换钱。","Tīngshuō, fàndiàn li kěyǐ huàn qián.","Nghe nói trong khách sạn có thể đổi tiền."],["玛丽","我们去问问吧。","Wǒmen qù wènwen ba.","Chúng ta đi hỏi thử xem."]]},{"t":"课文 2","c":[["玛丽","请问，这儿能不能换钱？","Qǐng wèn, zhèr néng bu néng huàn qián?","Xin hỏi, ở đây có đổi tiền được không?"],["营业员","能。您带的什么钱？","Néng. Nín dài de shénme qián?","Được. Chị mang theo tiền gì?"],["玛丽","美元。","Měiyuán.","Đô-la Mỹ."],["营业员","换多少？","Huàn duōshao?","Đổi bao nhiêu?"],["玛丽","五百美元。一美元换多少人民币？","Wǔbǎi Měiyuán. Yì Měiyuán huàn duōshao rénmínbì?","Năm trăm đô-la Mỹ. Một đô-la đổi được bao nhiêu nhân dân tệ?"],["营业员","八块二毛七。请您写一下儿钱数。再写一下儿名字。","Bā kuài èr máo qī. Qǐng nín xiě yíxiàr qián shù. Zài xiě yíxiàr míngzi.","Tám đồng hai hào bảy xu. Xin chị viết số tiền. Rồi viết thêm tên."],["玛丽","这样写，对不对？","Zhèyàng xiě, duì bu duì?","Viết thế này, có đúng không?"],["营业员","对。给您钱，请数一数。","Duì. Gěi nín qián, qǐng shǔ yi shǔ.","Đúng rồi. Gửi chị tiền, xin chị đếm lại."],["玛丽","谢谢！","Xièxie!","Cảm ơn!"],["大卫","时间不早了。我们快走吧！","Shíjiān bù zǎo le. Wǒmen kuài zǒu ba!","Muộn rồi. Chúng ta đi nhanh lên!"]]}]},{"n":15,"ten":"我要打国际电话","doan":[{"t":"课文 1","c":[["和子","有纪念邮票吗？","Yǒu jìniàn yóupiào ma?","Có tem kỷ niệm không ạ?"],["营业员","有，这是新出的。","Yǒu, zhè shì xīn chū de.","Có, đây là loại mới phát hành."],["和子","好。买两套。还有好看的吗？","Hǎo. Mǎi liǎng tào. Hái yǒu hǎokàn de ma?","Được. Tôi mua hai bộ. Còn loại nào đẹp nữa không?"],["营业员","你看看，这几种怎么样？","Nǐ kànkan, zhè jǐ zhǒng zěnmeyàng?","Chị xem thử, mấy loại này thế nào?"],["和子","请你帮我挑挑。","Qǐng nǐ bāng wǒ tiāotiao.","Nhờ chị chọn giúp tôi."],["营业员","我看这四种都很好。","Wǒ kàn zhè sì zhǒng dōu hěn hǎo.","Tôi thấy bốn loại này đều đẹp."],["和子","那一样买一套吧。这儿能打国际电话吗？","Nà yí yàng mǎi yí tào ba. Zhèr néng dǎ guójì diànhuà ma?","Vậy mỗi kiểu mua một bộ. Ở đây gọi điện thoại quốc tế được không?"],["营业员","能，在那儿。买电话卡吗？","Néng, zài nàr. Mǎi diànhuàkǎ ma?","Được, ở đằng kia. Chị có mua thẻ điện thoại không?"],["和子","不，我有。","Bù, wǒ yǒu.","Không, tôi có rồi."]]},{"t":"课文 2","c":[["和子","小姐，我要打国际电话。","Xiǎojie, wǒ yào dǎ guójì diànhuà.","Chị ơi, tôi muốn gọi điện thoại quốc tế."],["营业员","你打到哪儿？","Nǐ dǎ dào nǎr?","Chị gọi đi đâu?"],["和子","东京。我的电话号码是（03）390-78160。","Dōngjīng. Wǒ de diànhuà hàomǎ shì (líng sān) sān jiǔ líng - qī bā yāo liù líng.","Tô-ky-ô. Số điện thoại của tôi là (03) 390-78160."],["营业员","还要拨地区号。","Hái yào bō dìqū hào.","Còn phải quay mã vùng nữa."],["和子","东京的地区号是多少？","Dōngjīng de dìqū hào shì duōshao?","Mã vùng của Tô-ky-ô là bao nhiêu?"],["营业员","不拨03，拨00813。","Bù bō líng sān, bō líng líng bā yāo sān.","Không quay 03, quay 00813."]]},{"t":"课文 3","c":[["营业员","电话打通了吗？","Diànhuà dǎ tōng le ma?","Điện thoại gọi được chưa?"],["和子","谢谢！打通了。","Xièxie! Dǎ tōng le.","Cảm ơn chị! Gọi được rồi."]]}]},{"n":16,"ten":"你看过京剧吗？","doan":[{"t":"课文 1","c":[["玛丽","你看过京剧吗？","Nǐ kànguo jīngjù ma?","Bạn xem Kinh kịch bao giờ chưa?"],["大卫","没看过。","Méi kànguo.","Chưa xem bao giờ."],["玛丽","听说很有意思。","Tīngshuō hěn yǒuyìsi.","Nghe nói hay lắm."],["大卫","我很想看，你呢？","Wǒ hěn xiǎng kàn, nǐ ne?","Mình rất muốn xem, còn bạn?"],["玛丽","我也很想看。你知道哪儿演吗？","Wǒ yě hěn xiǎng kàn. Nǐ zhīdao nǎr yǎn ma?","Mình cũng rất muốn xem. Bạn biết ở đâu diễn không?"],["大卫","人民剧场常演。","Rénmín Jùchǎng cháng yǎn.","Rạp hát Nhân Dân thường diễn."],["玛丽","那我们星期六去看，好不好？","Nà wǒmen xīngqīliù qù kàn, hǎo bu hǎo?","Vậy thứ bảy chúng ta đi xem, được không?"],["大卫","当然好。明天我去买票。","Dāngrán hǎo. Míngtiān wǒ qù mǎi piào.","Đương nhiên là được. Mai mình đi mua vé."],["玛丽","买到票以后告诉我。","Mǎidào piào yǐhòu gàosu wǒ.","Mua được vé thì bảo mình nhé."],["大卫","好。","Hǎo.","Ừ."]]},{"t":"课文 2","c":[["和子","听说，烤鸭是北京的名菜。","Tīngshuō, kǎoyā shì Běijīng de míngcài.","Nghe nói vịt quay là món nổi tiếng của Bắc Kinh."],["玛丽","我还没吃过呢！","Wǒ hái méi chīguo ne!","Mình còn chưa ăn bao giờ đấy!"],["和子","我们应该去尝一尝。","Wǒmen yīnggāi qù cháng yi cháng.","Chúng ta nên đi ăn thử xem."],["玛丽","二十八号晚上我没事，你呢？","Èrshíbā hào wǎnshang wǒ méi shì, nǐ ne?","Tối ngày 28 mình rảnh, còn bạn?"],["和子","不行，有朋友来看我。","Bù xíng, yǒu péngyou lái kàn wǒ.","Không được, có bạn đến thăm mình."],["玛丽","三十号晚上怎么样？","Sānshí hào wǎnshang zěnmeyàng?","Tối ngày 30 thì sao?"],["和子","可以。","Kěyǐ.","Được."]]}]},{"n":17,"ten":"去动物园","doan":[{"t":"课文 1","c":[["张","这两天天气很好。我们出去玩儿玩儿吧。","Zhè liǎng tiān tiānqì hěn hǎo. Wǒmen chūqu wánr wanr ba.","Mấy hôm nay thời tiết rất tốt. Chúng ta ra ngoài chơi một chút nhé."],["和子","去哪儿玩儿好呢？","Qù nǎr wánr hǎo ne?","Đi đâu chơi cho vui đây?"],["张","去北海公园，看看花儿，划划船，多好啊！","Qù Běihǎi Gōngyuán, kànkan huār, huáhua chuán, duō hǎo a!","Đi công viên Bắc Hải, ngắm hoa, chèo thuyền, thích biết bao!"],["和子","上星期我去过了，去别的地方吧。","Shàng xīngqī wǒ qùguo le, qù biéde dìfang ba.","Tuần trước tôi đi rồi, đi chỗ khác đi."],["张","去动物园怎么样？","Qù dòngwùyuán zěnmeyàng?","Đi sở thú thì sao?"],["和子","行，还可以看看熊猫呢。","Xíng, hái kěyǐ kànkan xióngmāo ne.","Được, còn có thể xem gấu trúc nữa."],["张","什么时候去？","Shénme shíhou qù?","Khi nào đi?"],["和子","星期天吧。","Xīngqītiān ba.","Chủ nhật nhé."]]},{"t":"课文 2","c":[["和子","你认识西川一郎吗？","Nǐ rènshi Xīchuān Yīláng ma?","Bạn có quen Nishikawa Ichirō không?"],["刘京","当然认识。去年他在这儿学过汉语。","Dāngrán rènshi. Qùnián tā zài zhèr xuéguo Hànyǔ.","Đương nhiên quen. Năm ngoái anh ấy từng học tiếng Hán ở đây."],["和子","你知道吗？明天他来北京。","Nǐ zhīdao ma? Míngtiān tā lái Běijīng.","Bạn biết không? Ngày mai anh ấy đến Bắc Kinh."],["刘京","不知道。他上午到还是下午到？","Bù zhīdao. Tā shàngwǔ dào háishi xiàwǔ dào?","Không biết. Anh ấy đến buổi sáng hay buổi chiều?"],["和子","下午两点，我去机场接他。","Xiàwǔ liǎng diǎn, wǒ qù jīchǎng jiē tā.","Hai giờ chiều, mình ra sân bay đón anh ấy."],["刘京","明天下午没有课，我跟你一起去。","Míngtiān xiàwǔ méi yǒu kè, wǒ gēn nǐ yìqǐ qù.","Chiều mai không có tiết, mình đi cùng bạn."],["和子","好的。","Hǎo de.","Được."],["刘京","怎么去？","Zěnme qù?","Đi bằng gì?"],["和子","坐车去，一点我去叫你。","Zuò chē qù, yì diǎn wǒ qù jiào nǐ.","Đi xe, một giờ mình qua gọi bạn."]]}]},{"n":18,"ten":"路上辛苦了？","doan":[{"t":"课文 1","c":[["和子","从东京来的飞机到了吗？","Cóng Dōngjīng lái de fēijī dào le ma?","Máy bay từ Tô-ky-ô đã đến chưa?"],["服务员","还没到。","Hái méi dào.","Vẫn chưa đến."],["和子","为什么？","Wèishénme?","Tại sao vậy?"],["服务员","晚点了。飞机现在在上海。","Wǎn diǎn le. Fēijī xiànzài zài Shànghǎi.","Trễ giờ rồi. Máy bay bây giờ đang ở Thượng Hải."],["和子","起飞了吗？","Qǐfēi le ma?","Cất cánh chưa?"],["服务员","快要起飞了。","Kuài yào qǐfēi le.","Sắp cất cánh rồi."],["和子","什么时候能到？","Shénme shíhou néng dào?","Khi nào thì đến được?"],["服务员","大概三点半能到。","Dàgài sān diǎn bàn néng dào.","Khoảng ba giờ rưỡi thì đến."],["和子","刘京，我们先去喝点儿水，一会儿再来这儿吧。","Liú Jīng, wǒmen xiān qù hē diǎnr shuǐ, yíhuìr zài lái zhèr ba.","Lưu Kinh, chúng ta đi uống chút nước trước, lát nữa lại đến đây nhé."]]},{"t":"课文 2","c":[["和子","你看，西川来了。","Nǐ kàn, Xīchuān lái le.","Bạn xem, Nishikawa đến rồi."],["刘京","你好！路上辛苦了。","Nǐ hǎo! Lù shang xīnkǔ le.","Chào anh! Đi đường vất vả rồi."],["西川","你们好！刘京，你怎么知道我要来？","Nǐmen hǎo! Liú Jīng, nǐ zěnme zhīdao wǒ yào lái?","Chào các bạn! Lưu Kinh, sao bạn biết là tôi sẽ đến?"],["刘京","是她告诉我的。","Shì tā gàosu wǒ de.","Chính cô ấy nói cho mình biết."],["西川","感谢你们来接我。","Gǎnxiè nǐmen lái jiē wǒ.","Cảm ơn các bạn đã đến đón tôi."],["和子","我们出去吧！","Wǒmen chūqu ba!","Chúng ta ra ngoài đi thôi!"],["西川","等一等，还有贸易公司的人接我呢。","Děng yi děng, hái yǒu màoyì gōngsī de rén jiē wǒ ne.","Đợi một chút, còn có người của công ty thương mại đón mình nữa."],["刘京","好，我们在这儿等你。","Hǎo, wǒmen zài zhèr děng nǐ.","Được, chúng mình đợi bạn ở đây."]]}]},{"n":19,"ten":"欢迎你！","doan":[{"t":"课文 1","c":[["王","您好！西川先生。我是王大年，公司的翻译。","Nín hǎo! Xīchuān xiānsheng. Wǒ shì Wáng Dànián, gōngsī de fānyì.","Chào ông! Ông Nishikawa. Tôi là Vương Đại Niên, phiên dịch của công ty."],["西川","谢谢您来接我。","Xièxie nín lái jiē wǒ.","Cảm ơn ông đã đến đón tôi."],["王","别客气，路上辛苦了。","Bié kèqi, lù shang xīnkǔ le.","Đừng khách sáo, trên đường vất vả rồi."],["西川","一点儿也不累，很顺利。","Yìdiǎnr yě bú lèi, hěn shùnlì.","Không mệt chút nào, rất thuận lợi."],["王","汽车在外边，我们送您去饭店。","Qìchē zài wàibian, wǒmen sòng nín qù fàndiàn.","Xe ô tô ở bên ngoài, chúng tôi đưa ông về khách sạn."],["西川","我还有两个朋友。","Wǒ hái yǒu liǎng ge péngyou.","Tôi còn có hai người bạn nữa."],["王","那一起走吧。","Nà yìqǐ zǒu ba.","Vậy cùng đi nhé."],["西川","谢谢！","Xièxie!","Cảm ơn!"]]},{"t":"课文 2","c":[["经理","欢迎您！西川先生。","Huānyíng nín! Xīchuān xiānsheng.","Hoan nghênh ông! Ông Nishikawa."],["西川","谢谢！","Xièxie!","Cảm ơn!"],["经理","您第一次来中国吗？","Nín dì yī cì lái Zhōngguó ma?","Lần đầu tiên ông đến Trung Quốc phải không?"],["西川","不，我以前来过。这是我们经理给您的信。","Bù, wǒ yǐqián láiguo. Zhè shì wǒmen jīnglǐ gěi nín de xìn.","Không, trước đây tôi từng đến. Đây là thư của giám đốc chúng tôi gửi cho ông."],["经理","麻烦您了。","Máfan nín le.","Làm phiền ông quá."],["西川","他问您好。","Tā wèn nín hǎo.","Ông ấy gửi lời hỏi thăm ông."],["经理","谢谢。今天晚上我们在北京饭店请您吃晚饭。","Xièxie. Jīntiān wǎnshang wǒmen zài Běijīng Fàndiàn qǐng nín chī wǎnfàn.","Cảm ơn. Tối nay chúng tôi mời ông dùng cơm tối ở khách sạn Bắc Kinh."],["西川","您太客气了，真不好意思。","Nín tài kèqi le, zhēn bùhǎoyìsi.","Ông khách sáo quá, thật ngại quá."],["经理","您有时间吗？","Nín yǒu shíjiān ma?","Ông có thời gian không?"],["西川","下午我去朋友那儿。晚上我没事。","Xiàwǔ wǒ qù péngyou nàr. Wǎnshang wǒ méi shì.","Chiều tôi đến chỗ bạn. Tối tôi không có việc gì."],["经理","我们去接您。","Wǒmen qù jiē nín.","Chúng tôi đến đón ông."],["西川","不用了，我可以打的，我从朋友那儿去。","Búyòng le, wǒ kěyǐ dǎdī, wǒ cóng péngyou nàr qù.","Khỏi cần, tôi có thể đi taxi, tôi đi từ chỗ bạn."]]}]},{"n":20,"ten":"为我们的友谊干杯！","doan":[{"t":"课文 1","c":[["翻译","西川先生，请这儿坐。","Xīchuān xiānsheng, qǐng zhèr zuò.","Ông Nishikawa, mời ngồi đây."],["西川","谢谢！","Xièxie!","Cảm ơn!"],["经理","这两天过得怎么样？","Zhè liǎng tiān guò de zěnmeyàng?","Hai hôm nay ông sống thế nào?"],["西川","过得很愉快。","Guò de hěn yúkuài.","Rất vui vẻ."],["翻译","您喜欢喝什么酒？","Nín xǐhuan hē shénme jiǔ?","Ông thích uống rượu gì?"],["西川","啤酒吧。","Píjiǔ ba.","Bia vậy."],["经理","您尝尝这个菜怎么样？","Nín chángchang zhè ge cài zěnmeyàng?","Ông nếm thử món này xem thế nào?"],["西川","很好吃。","Hěn hǎochī.","Rất ngon."],["经理","吃啊，别客气。","Chī a, bié kèqi.","Ăn đi, đừng khách sáo."],["西川","不客气。","Bú kèqi.","Không khách sáo đâu."],["经理","来，为我们的友谊干杯！","Lái, wèi wǒmen de yǒuyì gān bēi!","Nào, cạn ly vì tình hữu nghị của chúng ta!"],["翻译","干杯！","Gān bēi!","Cạn ly!"],["西川","干杯！","Gān bēi!","Cạn ly!"]]},{"t":"课文 2","c":[["刘京","我们先喝酒吧。","Wǒmen xiān hē jiǔ ba.","Chúng ta uống rượu trước nhé."],["西川","这个鱼做得真好吃。","Zhè ge yú zuò de zhēn hǎochī.","Món cá này nấu thật ngon."],["刘母","你们别客气，像在家一样。","Nǐmen bié kèqi, xiàng zài jiā yíyàng.","Các cháu đừng khách sáo, cứ như ở nhà nhé."],["西川","我们不客气。","Wǒmen bú kèqi.","Chúng cháu không khách sáo đâu ạ."],["刘母","吃饺子吧。","Chī jiǎozi ba.","Ăn sủi cảo đi."],["和子","我最喜欢吃饺子了。","Wǒ zuì xǐhuan chī jiǎozi le.","Cháu thích ăn sủi cảo nhất."],["刘京","听说你很会做日本菜。","Tīngshuō nǐ hěn huì zuò Rìběn cài.","Nghe nói bạn rất giỏi nấu món Nhật."],["和子","哪儿啊，我做得不好。","Nǎr a, wǒ zuò de bù hǎo.","Đâu có, mình nấu không ngon đâu."],["刘京","你怎么不吃了？","Nǐ zěnme bù chī le?","Sao bạn không ăn nữa?"],["和子","吃饱了。你们慢吃。","Chībǎo le. Nǐmen màn chī.","Mình no rồi. Các bạn ăn từ từ."]]}]}]},{"id":"boya","zh":"博雅汉语","vi":"Boya sơ cấp 1","bai":[{"n":1,"ten":"你好","doan":[{"t":"课文 1","c":[["大卫","你好!","Nǐ hǎo!","Chào bạn!"],["李军","你好!","Nǐ hǎo!","Chào bạn!"],["大卫","你是老师吗?","Nǐ shì lǎoshī ma?","Bạn có phải là giáo viên không?"],["李军","不是，我不是老师，我是学生。她是老师。","Bú shì, wǒ bú shì lǎoshī, wǒ shì xuésheng. Tā shì lǎoshī.","Không phải, mình không phải giáo viên, mình là học sinh. Cô ấy là giáo viên."],["大卫","谢谢。","Xièxie.","Cảm ơn."],["李军","不客气。","Bú kèqi.","Không có gì."]]},{"t":"课文 2","c":[["大卫","老师，您好!","Lǎoshī, nín hǎo!","Chào cô ạ!"],["王老师","你好！你是留学生吗?","Nǐ hǎo! Nǐ shì liúxuéshēng ma?","Chào em! Em có phải là lưu học sinh không?"],["大卫","是，我是留学生。","Shì, wǒ shì liúxuéshēng.","Dạ, em là lưu học sinh."],["王老师","你叫什么名字?","Nǐ jiào shénme míngzi?","Em tên là gì?"],["大卫","我叫大卫。","Wǒ jiào Dàwèi.","Em tên là David."]]}]},{"n":2,"ten":"你是哪国人","doan":[{"t":"课文 1","c":[["刘老师","同学们好！","Tóngxuémen hǎo!","Chào các em!"],["学生","老师好！","Lǎoshī hǎo!","Chúng em chào thầy ạ!"],["刘老师","我来介绍一下儿。我姓刘，叫刘明，是你们的老师。你叫什么名字？","Wǒ lái jièshào yíxiàr. Wǒ xìng Liú, jiào Liú Míng, shì nǐmen de lǎoshī. Nǐ jiào shénme míngzi?","Thầy xin giới thiệu một chút. Thầy họ Lưu, tên là Lưu Minh, là giáo viên của các em. Em tên là gì?"],["大卫","我叫大卫。","Wǒ jiào Dàwèi.","Em tên là David."],["刘老师","你是哪国人？","Nǐ shì nǎ guó rén?","Em là người nước nào?"],["大卫","我是美国人。","Wǒ shì Měiguó rén.","Em là người Mỹ."]]},{"t":"课文 2","c":[["大卫","我来介绍一下儿。她叫玛丽，他叫李军。","Wǒ lái jièshào yíxiàr. Tā jiào Mǎlì, tā jiào Lǐ Jūn.","Mình giới thiệu một chút nhé. Bạn nữ này tên là Mary, bạn nam này tên là Lý Quân."],["玛丽","认识你很高兴。","Rènshi nǐ hěn gāoxìng.","Rất vui được làm quen với bạn."],["李军","我也很高兴。你是美国人吗？","Wǒ yě hěn gāoxìng. Nǐ shì Měiguó rén ma?","Mình cũng rất vui. Bạn là người Mỹ à?"],["玛丽","不，我不是美国人，我是加拿大人。你呢？","Bù, wǒ bú shì Měiguó rén, wǒ shì Jiānádà rén. Nǐ ne?","Không, mình không phải người Mỹ, mình là người Canada. Còn bạn?"],["李军","我是中国人。","Wǒ shì Zhōngguó rén.","Mình là người Trung Quốc."]]}]},{"n":3,"ten":"那是你的书吗","doan":[{"t":"课文 1","c":[["大卫","玛丽，那是谁的书？是你的书吗？","Mǎlì, nà shì shéi de shū? Shì nǐ de shū ma?","Mary, kia là sách của ai vậy? Là sách của bạn à?"],["玛丽","不是，那是我同屋的书。","Bú shì, nà shì wǒ tóngwū de shū.","Không phải, đó là sách của bạn cùng phòng mình."],["大卫","是汉语课本吗？","Shì Hànyǔ kèběn ma?","Là giáo trình tiếng Hán à?"],["玛丽","不是，是《汉日词典》。","Bú shì, shì《Hàn-Rì Cídiǎn》.","Không phải, là cuốn \"Từ điển Hán–Nhật\"."],["大卫","什么词典？","Shénme cídiǎn?","Từ điển gì cơ?"],["玛丽","《汉日词典》，就是汉语、日语词典。","《Hàn-Rì Cídiǎn》, jiù shì Hànyǔ、Rìyǔ cídiǎn.","\"Từ điển Hán–Nhật\", tức là từ điển tiếng Hán – tiếng Nhật."]]},{"t":"课文 2","c":[["玛丽","这是什么杂志？","Zhè shì shénme zázhì?","Đây là tạp chí gì vậy?"],["中村","音乐杂志。","Yīnyuè zázhì.","Tạp chí âm nhạc."],["玛丽","是日本的杂志吗？","Shì Rìběn de zázhì ma?","Là tạp chí của Nhật à?"],["中村","不是，是中国的杂志。","Bú shì, shì Zhōngguó de zázhì.","Không phải, là tạp chí của Trung Quốc."],["玛丽","是你的杂志吗？","Shì nǐ de zázhì ma?","Là tạp chí của bạn à?"],["中村","不是，是我朋友的杂志。","Bú shì, shì wǒ péngyou de zázhì.","Không phải, là tạp chí của bạn mình."]]}]},{"n":4,"ten":"图书馆在哪儿","doan":[{"t":"课文 1","c":[["玛丽","同学，请问，图书馆在哪儿？","Tóngxué, qǐngwèn, túshūguǎn zài nǎr?","Bạn ơi, cho mình hỏi, thư viện ở đâu vậy?"],["学生A","对不起，我不是这个学校的学生，不知道。","Duìbuqǐ, wǒ bú shì zhège xuéxiào de xuésheng, bù zhīdào.","Xin lỗi, mình không phải sinh viên trường này, mình không biết."],["玛丽","没关系。","Méi guānxi.","Không sao đâu."]]},{"t":"课文 2","c":[["玛丽","同学，这儿是图书馆吗？","Tóngxué, zhèr shì túshūguǎn ma?","Bạn ơi, đây có phải là thư viện không?"],["学生B","不是，这是教学楼，图书馆在那儿，宿舍楼的北边。","Bú shì, zhè shì jiàoxuélóu, túshūguǎn zài nàr, sùshèlóu de běibian.","Không phải, đây là toà giảng đường. Thư viện ở đằng kia, phía bắc toà ký túc xá."],["玛丽","是左边的楼吗？","Shì zuǒbian de lóu ma?","Là toà nhà bên trái à?"],["学生B","不，是右边的楼。","Bù, shì yòubian de lóu.","Không, là toà bên phải."],["玛丽","谢谢。","Xièxie.","Cảm ơn bạn."],["学生B","不用谢。","Búyòng xiè.","Không có gì."]]}]},{"n":5,"ten":"在北京大学的东边","doan":[{"t":"课文 1","c":[["玛丽","你好！你叫什么名字？","Nǐ hǎo! Nǐ jiào shénme míngzi?","Chào bạn! Bạn tên là gì?"],["张红","我叫张红。你呢？","Wǒ jiào Zhāng Hóng. Nǐ ne?","Mình tên là Trương Hồng. Còn bạn?"],["玛丽","我叫玛丽。我是北京大学的留学生。我的专业是国际关系。你呢？","Wǒ jiào Mǎlì. Wǒ shì Běijīng Dàxué de liúxuéshēng. Wǒ de zhuānyè shì guójì guānxi. Nǐ ne?","Mình tên là Mary. Mình là du học sinh của Đại học Bắc Kinh. Chuyên ngành của mình là quan hệ quốc tế. Còn bạn?"],["张红","我是清华大学中文系的研究生。我的专业是现代文学。","Wǒ shì Qīnghuá Dàxué Zhōngwén xì de yánjiūshēng. Wǒ de zhuānyè shì xiàndài wénxué.","Mình là học viên sau đại học khoa tiếng Trung, Đại học Thanh Hoa. Chuyên ngành của mình là văn học hiện đại."],["玛丽","清华大学在哪儿？","Qīnghuá Dàxué zài nǎr?","Đại học Thanh Hoa ở đâu?"],["张红","在北京大学的东边。有空儿的时候，欢迎你去玩儿。","Zài Běijīng Dàxué de dōngbian. Yǒu kòngr de shíhou, huānyíng nǐ qù wánr.","Ở phía đông Đại học Bắc Kinh. Lúc nào rảnh, mời bạn sang chơi nhé."]]},{"t":"课文 2","c":[["大卫","请问，卫生间在哪儿？","Qǐngwèn, wèishēngjiān zài nǎr?","Cho mình hỏi, nhà vệ sinh ở đâu?"],["学生","在那儿，教室的旁边。","Zài nàr, jiàoshì de pángbiān.","Ở đằng kia, bên cạnh phòng học."],["大卫","是西边的教室吗？","Shì xībian de jiàoshì ma?","Là phòng học phía tây à?"],["学生","对。","Duì.","Đúng rồi."]]}]},{"n":6,"ten":"现在几点","doan":[{"t":"课文 1","c":[["玛丽","中村，日本的大学早上几点上课？","Zhōngcūn, Rìběn de dàxué zǎoshang jǐ diǎn shàngkè?","Nakamura, trường đại học ở Nhật sáng mấy giờ lên lớp?"],["中村","大部分是九点，我们学校是八点五十分。","Dà bùfen shì jiǔ diǎn, wǒmen xuéxiào shì bā diǎn wǔshí fēn.","Phần lớn là chín giờ, trường chúng tôi là tám giờ năm mươi phút."],["玛丽","几点下课？","Jǐ diǎn xiàkè?","Mấy giờ tan học?"],["中村","十点半。","Shí diǎn bàn.","Mười giờ rưỡi."],["玛丽","北京大学早上八点上课，太早了。","Běijīng Dàxué zǎoshang bā diǎn shàngkè, tài zǎo le.","Đại học Bắc Kinh sáng tám giờ lên lớp, sớm quá."]]},{"t":"课文 2","c":[["玛丽","大卫，讲座几点开始？","Dàwèi, jiǎngzuò jǐ diǎn kāishǐ?","David, buổi tọa đàm mấy giờ bắt đầu?"],["大卫","六点。","Liù diǎn.","Sáu giờ."],["玛丽","现在几点？","Xiànzài jǐ diǎn?","Bây giờ mấy giờ rồi?"],["大卫","差一刻六点。","Chā yī kè liù diǎn.","Còn kém một khắc nữa là sáu giờ (5:45)."],["玛丽","谢谢！一会儿见。","Xièxie! Yīhuìr jiàn.","Cảm ơn! Lát nữa gặp."]]}]},{"n":7,"ten":"明天你有课吗","doan":[{"t":"课文 1","c":[["玛丽","中村，明天你有课吗？","Zhōngcūn, míngtiān nǐ yǒu kè ma?","Nakamura, ngày mai bạn có lớp không?"],["中村","我上午有课，下午没有。","Wǒ shàngwǔ yǒu kè, xiàwǔ méiyǒu.","Buổi sáng tôi có lớp, buổi chiều không có."],["玛丽","你有自行车吧？","Nǐ yǒu zìxíngchē ba?","Bạn có xe đạp nhỉ?"],["中村","有。什么事？","Yǒu. Shénme shì?","Có. Có chuyện gì vậy?"],["玛丽","我明天下午去见朋友，可是我没有自行车……","Wǒ míngtiān xiàwǔ qù jiàn péngyou, kěshì wǒ méiyǒu zìxíngchē……","Ngày mai buổi chiều tôi đi gặp bạn, nhưng tôi không có xe đạp……"],["中村","没问题，我有。这是钥匙，车在楼下车棚里。","Méi wèntí, wǒ yǒu. Zhè shì yàoshi, chē zài lóu xià chēpéng lǐ.","Không vấn đề, tôi có. Đây là chìa khóa, xe ở trong nhà để xe tầng dưới."],["玛丽","是宿舍楼后边的车棚吗？","Shì sùshèlóu hòubiān de chēpéng ma?","Là nhà để xe phía sau tòa ký túc xá phải không?"],["中村","对。","Duì.","Đúng vậy."]]},{"t":"课文 2","c":[["大卫","玛丽，今天晚上你有时间吗？","Mǎlì, jīntiān wǎnshang nǐ yǒu shíjiān ma?","Mary, tối hôm nay bạn có thời gian không?"],["玛丽","有。有事吗？","Yǒu. Yǒu shì ma?","Có. Có việc gì không?"],["大卫","学校电影院有电影，你去吗？","Xuéxiào diànyǐngyuàn yǒu diànyǐng, nǐ qù ma?","Rạp chiếu phim trường có phim, bạn đi không?"],["玛丽","什么电影？","Shénme diànyǐng?","Phim gì vậy?"],["大卫","我不知道名字，可是听说很有名。","Wǒ bù zhīdào míngzi, kěshì tīngshuō hěn yǒumíng.","Tôi không biết tên, nhưng nghe nói rất nổi tiếng."],["玛丽","我当然去。","Wǒ dāngrán qù.","Tất nhiên tôi đi."]]}]},{"n":8,"ten":"你的电话号码是多少","doan":[{"t":"课文","c":[["张红","玛丽，周末你有空儿吗？","Mǎlì, zhōumò nǐ yǒu kòngr ma?","Mary, cuối tuần bạn có rảnh không?"],["玛丽","有。什么事？","Yǒu. Shénme shì?","Có. Có chuyện gì vậy?"],["张红","来我们学校玩儿吧！","Lái wǒmen xuéxiào wánr ba!","Đến trường chúng mình chơi đi!"],["玛丽","好啊！不过，去你们学校怎么走呢？","Hǎo a! Búguò, qù nǐmen xuéxiào zěnme zǒu ne?","Được thôi! Nhưng, đến trường các bạn đi đường nào?"],["张红","21路和106路公共汽车都到。骑自行车也很快，十五分钟就到。","Èryāo lù hé yāo líng liù lù gōnggòng qìchē dōu dào. Qí zìxíngchē yě hěn kuài, shíwǔ fēnzhōng jiù dào.","Xe buýt tuyến 21 và 106 đều đến. Đạp xe cũng rất nhanh, 15 phút là tới."],["玛丽","你的宿舍在哪儿？","Nǐ de sùshè zài nǎr?","Ký túc xá của bạn ở đâu?"],["张红","在校园的东南边，是东5号楼。","Zài xiàoyuán de dōngnán biān, shì dōng wǔ hào lóu.","Ở phía đông nam khuôn viên, là tòa nhà Đông 5."],["玛丽","你的房间号是多少？","Nǐ de fángjiān hào shì duōshao?","Số phòng của bạn là bao nhiêu?"],["张红","502号。我的宿舍是东5号楼502室。","Wǔ líng èr hào. Wǒ de sùshè shì dōng wǔ hào lóu wǔ líng èr shì.","Số 502. Ký túc xá của tôi là phòng 502 tòa nhà Đông 5."],["玛丽","你的电话号码是多少？","Nǐ de diànhuà hàomǎ shì duōshao?","Số điện thoại của bạn là bao nhiêu?"],["张红","63861023。你有手机吗？","Liù sān bā liù yāo líng èr sān. Nǐ yǒu shǒujī ma?","63861023. Bạn có điện thoại di động không?"],["玛丽","没有，不过我朋友有。","Méiyǒu, búguò wǒ péngyou yǒu.","Không có, nhưng bạn tôi có."],["张红","号码是多少？","Hàomǎ shì duōshao?","Số là bao nhiêu?"],["玛丽","13695670132。","Yāo sān liù jiǔ wǔ liù qī líng yāo sān èr.","13695670132."],["张红","好，我等你。","Hǎo, wǒ děng nǐ.","Được rồi, tôi đợi bạn."]]}]},{"n":9,"ten":"多少钱一瓶","doan":[{"t":"课文 1","c":[["大卫","师傅，我买啤酒。","Shīfu, wǒ mǎi píjiǔ.","Thầy ơi, tôi mua bia."],["售货员","你买几瓶？","Nǐ mǎi jǐ píng?","Anh mua mấy chai?"],["大卫","多少钱一瓶？","Duōshao qián yī píng?","Bao nhiêu tiền một chai?"],["售货员","三块五。","Sān kuài wǔ.","Ba đồng rưỡi."],["大卫","我买两瓶，再买两瓶水。","Wǒ mǎi liǎng píng, zài mǎi liǎng píng shuǐ.","Tôi mua hai chai, thêm hai chai nước nữa."],["售货员","两瓶啤酒七块，两瓶水两块四，一共是九块四毛钱。","Liǎng píng píjiǔ qī kuài, liǎng píng shuǐ liǎng kuài sì, yīgòng shì jiǔ kuài sì máo qián.","Hai chai bia bảy đồng, hai chai nước hai đồng bốn, tổng cộng là chín đồng bốn hào."],["大卫","给你钱。","Gěi nǐ qián.","Đưa tiền cho chị đây."]]},{"t":"课文 2","c":[["玛丽","小姐，有英汉词典吗？","Xiǎojiě, yǒu Yīng-Hàn cídiǎn ma?","Cô ơi, có từ điển Anh-Hoa không?"],["售货员","有。你看，这些都是，你要哪本呢？","Yǒu. Nǐ kàn, zhèxiē dōu shì, nǐ yào nǎ běn ne?","Có. Cô xem, tất cả đây đều là, cô muốn lấy quyển nào?"],["玛丽","我要这本小词典。多少钱一本？","Wǒ yào zhè běn xiǎo cídiǎn. Duōshao qián yī běn?","Tôi lấy quyển từ điển nhỏ này. Bao nhiêu tiền một quyển?"],["售货员","二十二块。","Èrshí'èr kuài.","Hai mươi hai đồng."],["玛丽","对不起，我没有零钱。","Duìbuqǐ, wǒ méiyǒu língqián.","Xin lỗi, tôi không có tiền lẻ."],["售货员","没关系。","Méi guānxi.","Không sao."]]}]},{"n":10,"ten":"你家有几口人","doan":[{"t":"课文","c":[["玛丽","这是你的照片吗？","Zhè shì nǐ de zhàopiàn ma?","Đây là ảnh của bạn à?"],["张红","对，是我家的照片。","Duì, shì wǒ jiā de zhàopiàn.","Đúng, là ảnh gia đình mình."],["玛丽","你家有几口人？","Nǐ jiā yǒu jǐ kǒu rén?","Nhà bạn có mấy người?"],["张红","我家有五口人：爷爷、奶奶、爸爸、妈妈和我。","Wǒ jiā yǒu wǔ kǒu rén: yéye, nǎinai, bàba, māma hé wǒ.","Nhà mình có năm người: ông, bà, bố, mẹ và mình."],["玛丽","你没有哥哥姐姐吗？","Nǐ méiyǒu gēge jiějie ma?","Bạn không có anh chị sao?"],["张红","没有，现在中国家庭一般只有一个孩子。玛丽，你家都有什么人？","Méiyǒu, xiànzài Zhōngguó jiātíng yìbān zhǐ yǒu yí ge háizi. Mǎlì, nǐ jiā dōu yǒu shénme rén?","Không có, hiện nay gia đình Trung Quốc thường chỉ có một đứa con. Mary, nhà bạn có những ai?"],["玛丽","我家有爸爸、妈妈、哥哥、弟弟、妹妹，还有一条狗。","Wǒ jiā yǒu bàba, māma, gēge, dìdi, mèimei, hái yǒu yì tiáo gǒu.","Nhà mình có bố, mẹ, anh trai, em trai, em gái, còn có một con chó."],["张红","一共六口人？","Yígòng liù kǒu rén?","Tổng cộng sáu người?"],["玛丽","不，七口。","Bù, qī kǒu.","Không, bảy người."],["张红","爸爸、妈妈、一个哥哥、一个弟弟、一个妹妹和你，六口，对吧？","Bàba, māma, yí ge gēge, yí ge dìdi, yí ge mèimei hé nǐ, liù kǒu, duì ba?","Bố, mẹ, một anh trai, một em trai, một em gái và bạn, sáu người, đúng không?"],["玛丽","不对，还有一条狗。","Bú duì, hái yǒu yì tiáo gǒu.","Không đúng, còn có một con chó nữa."],["张红","是这样……","Shì zhèyàng……","Ra là vậy…"]]}]}]},{"id":"yuedu","zh":"汉语阅读教程","vi":"Đọc hiểu Hán ngữ 1","bai":[{"n":16,"ten":"","doan":[{"t":"会话","c":[["山田","玛丽，你去哪儿？","Mǎlì, nǐ qù nǎr?","Mary, cậu đi đâu đấy?"],["玛丽","我去图书馆。","Wǒ qù túshūguǎn.","Tớ đi thư viện."],["山田","你去借书吗？","Nǐ qù jiè shū ma?","Cậu đi mượn sách à?"],["玛丽","对，借书，也还书。","Duì, jiè shū, yě huán shū.","Đúng vậy, mượn sách, và cũng trả sách nữa."],["山田","你常常去图书馆吗？","Nǐ chángcháng qù túshūguǎn ma?","Cậu có thường đi thư viện không?"],["玛丽","常去。我常常在那儿看书，有时候查资料。你呢？","Cháng qù. Wǒ chángcháng zài nàr kàn shū, yǒu shíhou chá zīliào. Nǐ ne?","Đi thường xuyên chứ. Tớ thường ở đó đọc sách, thỉnh thoảng tra tài liệu. Còn cậu thì sao?"],["山田","我不常去。","Wǒ bù cháng qù.","Tớ không thường đi."],["玛丽","今天想跟我一起去吗？","Jīntiān xiǎng gēn wǒ yìqǐ qù ma?","Hôm nay cậu có muốn đi cùng tớ không?"],["山田","好，我也去借几本书。","Hǎo, wǒ yě qù jiè jǐ běn shū.","Được, tớ cũng đi mượn vài quyển sách."]]},{"t":"短文","c":[["","我们学校有一个图书馆。","Wǒmen xuéxiào yǒu yí gè túshūguǎn.","Trường chúng tôi có một thư viện."],["","图书馆很大，有很多书。","Túshūguǎn hěn dà, yǒu hěn duō shū.","Thư viện rất lớn, có rất nhiều sách."],["","每天都有很多人去那儿看书、借书、还书。","Měitiān dōu yǒu hěn duō rén qù nàr kàn shū, jiè shū, huán shū.","Mỗi ngày đều có rất nhiều người đến đó đọc sách, mượn sách, trả sách."],["","我也常常去图书馆。","Wǒ yě chángcháng qù túshūguǎn.","Tôi cũng thường đến thư viện."],["","有时候我去那儿看书、学习，有时候我去那儿查资料。","Yǒu shíhou wǒ qù nàr kàn shū, xuéxí, yǒu shíhou wǒ qù nàr chá zīliào.","Thỉnh thoảng tôi đến đó đọc sách, học bài, thỉnh thoảng tôi đến đó tra tài liệu."],["","今天我要去那儿查资料，我想写一篇文章，是关于中国历史的。","Jīntiān wǒ yào qù nàr chá zīliào, wǒ xiǎng xiě yì piān wénzhāng, shì guānyú Zhōngguó lìshǐ de.","Hôm nay tôi phải đến đó tra tài liệu, tôi muốn viết một bài văn, về lịch sử Trung Quốc."],["","这是我第一次用汉语写文章。","Zhè shì wǒ dì-yī cì yòng Hànyǔ xiě wénzhāng.","Đây là lần đầu tiên tôi viết văn bằng tiếng Trung."]]}]},{"n":17,"ten":"","doan":[{"t":"会话","c":[["玛丽","山田，你在做什么呢？","Shāntián, nǐ zài zuò shénme ne?","Sơn Điền, cậu đang làm gì đấy?"],["山田","听音乐呢。有事吗？","Tīng yīnyuè ne. Yǒu shì ma?","Tớ đang nghe nhạc. Cậu có việc gì à?"],["玛丽","下午我要去商店买东西，你跟我一起去吧。","Xiàwǔ wǒ yào qù shāngdiàn mǎi dōngxi, nǐ gēn wǒ yìqǐ qù ba.","Chiều nay tớ phải đi cửa hàng mua đồ, cậu đi cùng tớ nhé."],["山田","下午我有阅读课，下课以后去，行吗？","Xiàwǔ wǒ yǒu yuèdú kè, xiàkè yǐhòu qù, xíng ma?","Chiều nay tớ có tiết đọc, tan học rồi đi có được không?"],["玛丽","行，我们四点在学校门口见面。","Xíng, wǒmen sì diǎn zài xuéxiào ménkǒu jiànmiàn.","Được, chúng ta hẹn 4 giờ gặp nhau ở cổng trường."],["山田","玛丽，你哪天有综合课？","Mǎlì, nǐ nǎ tiān yǒu zōnghé kè?","Mary, cậu có môn tổng hợp vào ngày nào?"],["玛丽","我每天都有综合课。","Wǒ měitiān dōu yǒu zōnghé kè.","Ngày nào tớ cũng có môn tổng hợp."],["山田","听力课和阅读课呢？","Tīnglì kè hé yuèdú kè ne?","Thế còn môn nghe và môn đọc thì sao?"],["玛丽","星期一和星期三有听力课，星期二和星期四有阅读课。","Xīngqīyī hé xīngqīsān yǒu tīnglì kè, xīngqī'èr hé xīngqīsì yǒu yuèdú kè.","Thứ Hai và thứ Tư có môn nghe, thứ Ba và thứ Năm có môn đọc."],["山田","有汉字课吗？","Yǒu hànzì kè ma?","Có môn chữ Hán không?"],["玛丽","有，星期三下午有汉字课。","Yǒu, xīngqīsān xiàwǔ yǒu hànzì kè.","Có, chiều thứ Tư có môn chữ Hán."]]},{"t":"短文","c":[["","今天是星期日，马丁起床后问山本：“你今天做什么？”","Jīntiān shì xīngqīrì, Mǎdīng qǐchuáng hòu wèn Shānběn: “Nǐ jīntiān zuò shénme?”","Hôm nay là chủ nhật, Martin ngủ dậy liền hỏi Yamamoto: “Hôm nay cậu làm gì?”"],["","山本想了想，说：“今天要做的事很多。","Shānběn xiǎngle xiǎng, shuō: “Jīntiān yào zuò de shì hěn duō.","Yamamoto suy nghĩ một lát, nói: “Hôm nay có rất nhiều việc phải làm."],["","上午我要写阅读课的作业，预习星期一的语法和生词。","Shàngwǔ wǒ yào xiě yuèdú kè de zuòyè, yùxí xīngqīyī de yǔfǎ hé shēngcí.","Buổi sáng tớ phải làm bài tập môn đọc, xem trước ngữ pháp và từ mới của thứ Hai."],["","下午我去邮局寄信，还要去银行换钱，然后去书店买一本《日汉词典》，","Xiàwǔ wǒ qù yóujú jì xìn, hái yào qù yínháng huàn qián, ránhòu qù shūdiàn mǎi yì běn 《Rì-Hàn Cídiǎn》,","buổi chiều tớ đi bưu điện gửi thư, còn phải đi ngân hàng đổi tiền, sau đó đi hiệu sách mua một quyển 《Từ điển Nhật-Hán》,"],["","晚上去大使馆看朋友。”","wǎnshang qù dàshǐguǎn kàn péngyou.”","buổi tối đi đại sứ quán thăm bạn.”"],["","马丁说：“今天你真忙！","Mǎdīng shuō: “Jīntiān nǐ zhēn máng!","Martin nói: “Hôm nay cậu bận thật đấy!"],["","我下午跟你一起去邮局买杂志，然后回宿舍看杂志、听音乐。”","Wǒ xiàwǔ gēn nǐ yìqǐ qù yóujú mǎi zázhì, ránhòu huí sùshè kàn zázhì, tīng yīnyuè.”","Chiều nay tớ cùng cậu đi bưu điện mua tạp chí, sau đó về ký túc xá đọc tạp chí, nghe nhạc.”"]]}]},{"n":18,"ten":"","doan":[{"t":"会话","c":[["玛丽","山田，你去哪儿？","Shāntián, nǐ qù nǎr?","Sơn Điền, cậu đi đâu đấy?"],["山田","我去图书馆借书。","Wǒ qù túshūguǎn jiè shū.","Tớ đi thư viện mượn sách."],["玛丽","你替我还一本书，行吗？","Nǐ tì wǒ huán yì běn shū, xíng ma?","Cậu trả giúp tớ một quyển sách được không?"],["山田","没问题。玛丽，你去哪儿？","Méi wèntí. Mǎlì, nǐ qù nǎr?","Không thành vấn đề. Mary, cậu đi đâu?"],["玛丽","去买票，明天我跟朋友一起去上海。","Qù mǎi piào, míngtiān wǒ gēn péngyou yìqǐ qù Shànghǎi.","Đi mua vé, ngày mai tớ cùng bạn đi Thượng Hải."],["山田","去旅行？","Qù lǚxíng?","Đi du lịch à?"],["玛丽","不，去工作，给我的朋友当翻译。","Bù, qù gōngzuò, gěi wǒ de péngyou dāng fānyì.","Không, đi làm việc, làm phiên dịch cho bạn tớ."],["山田","你们怎么去？坐飞机去还是坐火车去？","Nǐmen zěnme qù? Zuò fēijī qù háishi zuò huǒchē qù?","Các cậu đi bằng gì? Đi máy bay hay đi tàu hỏa?"],["玛丽","坐飞机去。","Zuò fēijī qù.","Đi bằng máy bay."],["山田","好，书我替你还，放心吧。","Hǎo, shū wǒ tì nǐ huán, fàngxīn ba.","Được, sách để tớ trả giúp cậu, yên tâm đi."],["玛丽","谢谢！","Xièxie!","Cảm ơn!"],["山田","不客气。","Bú kèqi.","Không có gì."]]},{"t":"短文","c":[["","马丁来中国学习汉语。","Mǎdīng lái Zhōngguó xuéxí Hànyǔ.","Martin đến Trung Quốc học tiếng Hán."],["","他刚认识很多新朋友，有老师、医生、公司职员，还有各国的留学生。","Tā gāng rènshi hěn duō xīn péngyou, yǒu lǎoshī, yīshēng, gōngsī zhíyuán, hái yǒu gè guó de liúxuéshēng.","Anh ấy vừa mới quen rất nhiều bạn mới, có giáo viên, bác sĩ, nhân viên công ty, còn có lưu học sinh các nước."],["","他们常常一起听音乐，一起说汉语，一起吃饭。","Tāmen chángcháng yìqǐ tīng yīnyuè, yìqǐ shuō Hànyǔ, yìqǐ chīfàn.","Họ thường cùng nhau nghe nhạc, cùng nói tiếng Hán, cùng ăn cơm."],["","上星期马丁的姐姐来中国了。","Shàng xīngqī Mǎdīng de jiějie lái Zhōngguó le.","Tuần trước chị gái của Martin đã đến Trung Quốc."],["","马丁要跟姐姐去上海旅行，","Mǎdīng yào gēn jiějie qù Shànghǎi lǚxíng,","Martin sẽ cùng chị gái đi Thượng Hải du lịch,"],["","他给姐姐当翻译，","tā gěi jiějie dāng fānyì,","anh ấy làm phiên dịch cho chị gái,"],["","他们想坐火车去。","tāmen xiǎng zuò huǒchē qù.","họ muốn đi bằng tàu hỏa."]]}]},{"n":19,"ten":"","doan":[{"t":"会话","c":[["玛丽","山田，你看这件衣服怎么样？","Shāntián, nǐ kàn zhè jiàn yīfu zěnmeyàng?","Sơn Điền, cậu xem bộ quần áo này thế nào?"],["山田","不好，颜色太深了。","Bù hǎo, yánsè tài shēn le.","Không đẹp, màu đậm quá."],["玛丽","这件红色的怎么样？","Zhè jiàn hóngsè de zěnmeyàng?","Cái màu đỏ này thì sao?"],["山田","长短还可以，是不是太红了？","Chángduǎn hái kěyǐ, shì bu shì tài hóng le?","Độ dài thì tạm được, có phải đỏ quá không?"],["玛丽","这件绿色的呢？","Zhè jiàn lǜsè de ne?","Còn cái màu xanh lá này?"],["山田","有点儿小。","Yǒudiǎnr xiǎo.","Hơi nhỏ."],["玛丽","这件浅蓝色的行吗？","Zhè jiàn qiǎnlánsè de xíng ma?","Cái màu xanh nhạt này được không?"],["山田","行，不长不短，颜色好，样子也很漂亮。穿这件吧。","Xíng, bù cháng bù duǎn, yánsè hǎo, yàngzi yě hěn piàoliang. Chuān zhè jiàn ba.","Được, không dài không ngắn, màu đẹp, kiểu dáng cũng rất đẹp. Mặc cái này đi."],["玛丽","行，穿这件。","Xíng, chuān zhè jiàn.","Ừ, mặc cái này."]]},{"t":"短文","c":[["","去哪儿买衣服？","Qù nǎr mǎi yīfu?","Đi đâu mua quần áo?"],["","最好是去商场和服装店。","Zuì hǎo shì qù shāngchǎng hé fúzhuāngdiàn.","Tốt nhất là đến trung tâm thương mại và cửa hàng thời trang."],["","可是在不同的地方，你买到的衣服会很不一样。","Kěshì zài bù tóng de dìfang, nǐ mǎidào de yīfu huì hěn bù yíyàng.","Nhưng ở những nơi khác nhau, quần áo bạn mua được sẽ rất khác nhau."],["","在很多大商场和名牌服装店里，","Zài hěn duō dà shāngchǎng hé míngpái fúzhuāngdiàn li,","Ở nhiều trung tâm thương mại lớn và cửa hàng thời trang hàng hiệu,"],["","都会有很多名牌服装，样子好看，也很贵。","dōu huì yǒu hěn duō míngpái fúzhuāng, yàngzi hǎokàn, yě hěn guì.","đều có rất nhiều quần áo hàng hiệu, kiểu dáng đẹp, nhưng cũng rất đắt."],["","在服装市场和一些小商店里，","Zài fúzhuāng shìchǎng hé yìxiē xiǎo shāngdiàn li,","Ở chợ quần áo và một số cửa hàng nhỏ,"],["","很多衣服样子也很好看，各种颜色的都有，也不太贵，","hěn duō yīfu yàngzi yě hěn hǎokàn, gè zhǒng yánsè de dōu yǒu, yě bú tài guì,","nhiều quần áo kiểu dáng cũng rất đẹp, màu nào cũng có, lại không đắt lắm,"],["","还可以问售货员：“可以便宜一点儿吗？”","hái kěyǐ wèn shòuhuòyuán: “Kěyǐ piányi yìdiǎnr ma?”","còn có thể hỏi người bán hàng: “Có thể rẻ hơn một chút không?”"],["","这样，你可以花不太多的钱买到很好看的衣服。","Zhèyàng, nǐ kěyǐ huā bú tài duō de qián mǎidào hěn hǎokàn de yīfu.","Như vậy, bạn có thể tiêu không nhiều tiền mà mua được quần áo rất đẹp."]]}]},{"n":20,"ten":"","doan":[{"t":"会话","c":[["张华","玛丽，你今天为什么这么高兴？","Mǎlì, nǐ jīntiān wèi shénme zhème gāoxìng?","Mary, sao hôm nay cậu vui thế?"],["玛丽","今天是我的生日。","Jīntiān shì wǒ de shēngrì.","Hôm nay là sinh nhật tớ."],["张华","是吗？祝你生日快乐！","Shì ma? Zhù nǐ shēngrì kuàilè!","Thế à? Chúc cậu sinh nhật vui vẻ!"],["玛丽","谢谢！","Xièxie!","Cảm ơn!"],["张华","玛丽，你今年多大？","Mǎlì, nǐ jīnnián duō dà?","Mary, năm nay cậu bao nhiêu tuổi?"],["玛丽","对不起，这是秘密，不能告诉你。","Duìbuqǐ, zhè shì mìmì, bù néng gàosu nǐ.","Xin lỗi, đây là bí mật, không thể nói cho cậu biết."],["张华","真对不起，我不知道。在中国，一般可以问年龄。","Zhēn duìbuqǐ, wǒ bù zhīdào. Zài Zhōngguó, yìbān kěyǐ wèn niánlíng.","Thật xin lỗi, tớ không biết. Ở Trung Quốc, thường thì có thể hỏi tuổi."],["玛丽","没关系。","Méi guānxi.","Không sao."],["张华","你打算怎么过生日呢？","Nǐ dǎsuàn zěnme guò shēngrì ne?","Cậu định tổ chức sinh nhật thế nào?"],["玛丽","安娜她们说开一个生日晚会，你也参加吧。","Ānnà tāmen shuō kāi yí ge shēngrì wǎnhuì, nǐ yě cānjiā ba.","Anna và các bạn nói sẽ tổ chức một buổi tiệc sinh nhật, cậu cũng đến dự nhé."],["张华","好。什么时间？","Hǎo. Shénme shíjiān?","Được. Mấy giờ?"],["玛丽","今晚7点，在我的宿舍。","Jīnwǎn qī diǎn, zài wǒ de sùshè.","7 giờ tối nay, ở ký túc xá của tớ."],["张华","我一定去。","Wǒ yídìng qù.","Tớ nhất định sẽ đến."]]},{"t":"短文","c":[["","今天是玛丽的生日。","Jīntiān shì Mǎlì de shēngrì.","Hôm nay là sinh nhật của Mary."],["","她第一次在中国过生日。","Tā dì-yī cì zài Zhōngguó guò shēngrì.","Đây là lần đầu tiên cô ấy đón sinh nhật ở Trung Quốc."],["","朋友们打算开一个生日晚会。","Péngyoumen dǎsuàn kāi yí ge shēngrì wǎnhuì.","Các bạn dự định tổ chức một buổi tiệc sinh nhật."],["","玛丽请张华也参加。","Mǎlì qǐng Zhāng Huá yě cānjiā.","Mary mời Trương Hoa cũng đến dự."],["","晚会在玛丽的宿舍举行。","Wǎnhuì zài Mǎlì de sùshè jǔxíng.","Buổi tiệc được tổ chức ở ký túc xá của Mary."],["","朋友们送给玛丽一些礼物：","Péngyoumen sòng gěi Mǎlì yìxiē lǐwù:","Các bạn tặng Mary một số món quà:"],["","安娜送玛丽一本词典；","Ānnà sòng Mǎlì yì běn cídiǎn;","Anna tặng Mary một cuốn từ điển;"],["","山田送玛丽一块手表；","Shāntián sòng Mǎlì yí kuài shǒubiǎo;","Yamada tặng Mary một chiếc đồng hồ đeo tay;"],["","田中送玛丽一束很漂亮的花儿；","Tiánzhōng sòng Mǎlì yí shù hěn piàoliang de huār;","Tanaka tặng Mary một bó hoa rất đẹp;"],["","张华送玛丽一只玩具小狗，","Zhāng Huá sòng Mǎlì yì zhī wánjù xiǎo gǒu,","Trương Hoa tặng Mary một chú chó đồ chơi,"],["","他说玛丽是1982年出生的，这一年是狗年。","tā shuō Mǎlì shì yī jiǔ bā èr nián chūshēng de, zhè yì nián shì gǒunián.","cậu ấy nói Mary sinh năm 1982, năm đó là năm con chó (năm Tuất)."],["","玛丽很喜欢大家送给她的礼物。","Mǎlì hěn xǐhuan dàjiā sòng gěi tā de lǐwù.","Mary rất thích những món quà mọi người tặng cô."],["","她请朋友们吃生日蛋糕，","Tā qǐng péngyoumen chī shēngrì dàngāo,","Cô mời các bạn ăn bánh sinh nhật,"],["","朋友们唱“生日歌”，祝玛丽生日快乐。","péngyoumen chàng “Shēngrì gē”, zhù Mǎlì shēngrì kuàilè.","các bạn hát bài “Chúc mừng sinh nhật”, chúc Mary sinh nhật vui vẻ."]]}]},{"n":21,"ten":"","doan":[{"t":"会话","c":[["山田","玛丽，你周末常常做什么？","Mǎlì, nǐ zhōumò chángcháng zuò shénme?","Mary, cuối tuần cậu thường làm gì?"],["玛丽","我星期六早上差一刻八点起床，八点半吃早饭。早饭后我骑自行车出去，有时候去看朋友，有时候去公园。","Wǒ xīngqīliù zǎoshang chà yí kè bā diǎn qǐchuáng, bā diǎn bàn chī zǎofàn. Zǎofàn hòu wǒ qí zìxíngchē chūqu, yǒu shíhou qù kàn péngyou, yǒu shíhou qù gōngyuán.","Sáng thứ Bảy tớ dậy lúc 8 giờ kém 15, 8 giờ rưỡi ăn sáng. Ăn sáng xong tớ đạp xe ra ngoài, có khi đi thăm bạn, có khi đi công viên."],["山田","你什么时候回学校？","Nǐ shénme shíhou huí xuéxiào?","Khi nào cậu về trường?"],["玛丽","下午回学校。晚上我常常跟朋友一起在饭馆儿吃晚饭。","Xiàwǔ huí xuéxiào. Wǎnshang wǒ chángcháng gēn péngyou yìqǐ zài fànguǎnr chī wǎnfàn.","Buổi chiều về trường. Buổi tối tớ thường cùng bạn ăn tối ở quán."],["山田","星期日你做什么呢？","Xīngqīrì nǐ zuò shénme ne?","Thế Chủ nhật cậu làm gì?"],["玛丽","星期日我常常在宿舍里看书，听音乐，预习下星期的生词、语法。","Xīngqīrì wǒ chángcháng zài sùshè li kàn shū, tīng yīnyuè, yùxí xià xīngqī de shēngcí, yǔfǎ.","Chủ nhật tớ thường ở ký túc xá đọc sách, nghe nhạc, chuẩn bị trước từ mới và ngữ pháp của tuần sau."],["山田","你常常给爸爸、妈妈打电话吗？","Nǐ chángcháng gěi bàba, māma dǎ diànhuà ma?","Cậu có hay gọi điện cho bố mẹ không?"],["玛丽","有时候打电话，有时候发微信。","Yǒu shíhou dǎ diànhuà, yǒu shíhou fā Wēixìn.","Có khi gọi điện, có khi nhắn WeChat."]]},{"t":"短文","c":[["","很多中国人常常早睡早起。","Hěn duō Zhōngguórén chángcháng zǎo shuì zǎo qǐ.","Nhiều người Trung Quốc thường ngủ sớm dậy sớm."],["","他们早上六点半起床，起床以后去锻炼身体，","Tāmen zǎoshang liù diǎn bàn qǐchuáng, qǐchuáng yǐhòu qù duànliàn shēntǐ,","Họ dậy lúc 6 giờ rưỡi sáng, dậy xong đi tập thể dục,"],["","七点吃早饭，八点上班。","qī diǎn chī zǎofàn, bā diǎn shàngbān.","7 giờ ăn sáng, 8 giờ đi làm."],["","上午工作四个小时，十二点一刻吃午饭。","Shàngwǔ gōngzuò sì ge xiǎoshí, shí'èr diǎn yí kè chī wǔfàn.","Buổi sáng làm việc 4 tiếng, 12 giờ 15 ăn trưa."],["","午饭后休息一会儿，下午工作四个小时。","Wǔfàn hòu xiūxi yíhuìr, xiàwǔ gōngzuò sì ge xiǎoshí.","Ăn trưa xong nghỉ một lát, buổi chiều làm việc 4 tiếng."],["","下班后很多人去商店、超市买菜，","Xiàbān hòu hěn duō rén qù shāngdiàn, chāoshì mǎi cài,","Tan làm, nhiều người đi cửa hàng, siêu thị mua thức ăn,"],["","然后回家做饭，晚饭在七点左右。","ránhòu huí jiā zuò fàn, wǎnfàn zài qī diǎn zuǒyòu.","rồi về nhà nấu cơm, bữa tối vào khoảng 7 giờ."],["","晚饭后人们常常看电视、看书、看报、聊天儿，","Wǎnfàn hòu rénmen chángcháng kàn diànshì, kàn shū, kàn bào, liáotiānr,","Ăn tối xong mọi người thường xem tivi, đọc sách, đọc báo, trò chuyện,"],["","很多人十点半左右睡觉。","hěn duō rén shí diǎn bàn zuǒyòu shuìjiào.","nhiều người đi ngủ khoảng 10 giờ rưỡi."]]}]},{"n":22,"ten":"","doan":[{"t":"会话","c":[["记者","你们好！我是记者，想跟你们谈谈。","Nǐmen hǎo! Wǒ shì jìzhě, xiǎng gēn nǐmen tántan.","Chào các bạn! Tôi là phóng viên, muốn nói chuyện với các bạn một chút."],["众人","好。","Hǎo.","Vâng."],["记者","请问，你们是做什么工作的？","Qǐngwèn, nǐmen shì zuò shénme gōngzuò de?","Xin hỏi, các bạn làm nghề gì?"],["山田","我来中国前也是一名记者。","Wǒ lái Zhōngguó qián yě shì yì míng jìzhě.","Trước khi đến Trung Quốc tôi cũng là một phóng viên."],["玛丽","我以前是英语老师。","Wǒ yǐqián shì Yīngyǔ lǎoshī.","Trước đây tôi là giáo viên tiếng Anh."],["安娜","我是大学生。","Wǒ shì dàxuéshēng.","Tôi là sinh viên đại học."],["山田","现在我们都是学生。","Xiànzài wǒmen dōu shì xuésheng.","Bây giờ chúng tôi đều là học sinh."],["记者","你们有什么爱好？","Nǐmen yǒu shénme àihào?","Các bạn có sở thích gì?"],["玛丽","我喜欢写汉字。汉字很难写，可是很有意思。","Wǒ xǐhuan xiě Hànzì. Hànzì hěn nán xiě, kěshì hěn yǒu yìsi.","Tôi thích viết chữ Hán. Chữ Hán rất khó viết, nhưng rất thú vị."],["安娜","我喜欢看京剧，京剧里的衣服很好看，音乐也好听。","Wǒ xǐhuan kàn jīngjù, jīngjù li de yīfu hěn hǎokàn, yīnyuè yě hǎotīng.","Tôi thích xem kinh kịch, trang phục trong kinh kịch rất đẹp, âm nhạc cũng hay."],["山田","我的爱好是体育，我喜欢中国功夫。","Wǒ de àihào shì tǐyù, wǒ xǐhuan Zhōngguó gōngfu.","Sở thích của tôi là thể thao, tôi thích võ thuật Trung Quốc."],["记者","是吗？那请你表演表演，好吗？","Shì ma? Nà qǐng nǐ biǎoyǎn biǎoyǎn, hǎo ma?","Thế à? Vậy mời bạn biểu diễn một chút được không?"],["山田","现在还不行，以后吧。","Xiànzài hái bù xíng, yǐhòu ba.","Bây giờ thì chưa được, để sau nhé."]]},{"t":"短文","c":[["","山田、安娜和玛丽是我的同班同学。","Shāntián, Ānnà hé Mǎlì shì wǒ de tóngbān tóngxué.","Yamada, Anna và Mary là bạn cùng lớp của tôi."],["","我们常常一起聊天儿。","Wǒmen chángcháng yìqǐ liáotiānr.","Chúng tôi thường cùng nhau trò chuyện."],["","山田说他喜欢中国功夫，他每天都练习。","Shāntián shuō tā xǐhuan Zhōngguó gōngfu, tā měi tiān dōu liànxí.","Yamada nói cậu ấy thích võ thuật Trung Quốc, ngày nào cũng luyện tập."],["","玛丽说她的爱好是中国书法，她觉得书法太有意思了。","Mǎlì shuō tā de àihào shì Zhōngguó shūfǎ, tā juéde shūfǎ tài yǒu yìsi le.","Mary nói sở thích của cô ấy là thư pháp Trung Quốc, cô thấy thư pháp thú vị lắm."],["","安娜喜欢看京剧，她说京剧里的衣服真漂亮。","Ānnà xǐhuan kàn jīngjù, tā shuō jīngjù li de yīfu zhēn piàoliang.","Anna thích xem kinh kịch, cô nói trang phục trong kinh kịch thật đẹp."],["","我的爱好是旅行，中国有很多好玩儿的地方，","Wǒ de àihào shì lǚxíng, Zhōngguó yǒu hěn duō hǎowánr de dìfang,","Sở thích của tôi là du lịch, Trung Quốc có rất nhiều nơi thú vị,"],["","上海、西安、杭州、桂林……啊，太多了！","Shànghǎi, Xī'ān, Hángzhōu, Guìlín…… à, tài duō le!","Thượng Hải, Tây An, Hàng Châu, Quế Lâm… ôi, nhiều quá!"],["","这些地方我都想去，我一定要去。","Zhèxiē dìfang wǒ dōu xiǎng qù, wǒ yídìng yào qù.","Những nơi này tôi đều muốn đi, tôi nhất định phải đi."]]}]},{"n":23,"ten":"","doan":[{"t":"会话","c":[["田中","山田，我想去书店看看，你们学校里有书店吗？","Shāntián, wǒ xiǎng qù shūdiàn kànkan, nǐmen xuéxiào li yǒu shūdiàn ma?","Yamada, tớ muốn đi hiệu sách xem chút, trong trường các cậu có hiệu sách không?"],["山田","有。","Yǒu.","Có."],["田中","书店离这儿远吗？","Shūdiàn lí zhèr yuǎn ma?","Hiệu sách cách đây có xa không?"],["山田","不远，就在宿舍楼的东边。","Bù yuǎn, jiù zài sùshèlóu de dōngbian.","Không xa, ngay phía đông khu ký túc xá."],["田中","我们现在去，好吗？","Wǒmen xiànzài qù, hǎo ma?","Bây giờ mình đi nhé?"],["山田","好。","Hǎo.","Được."],["田中","山田，你们学校有足球场吗？","Shāntián, nǐmen xuéxiào yǒu zúqiúchǎng ma?","Yamada, trường các cậu có sân bóng đá không?"],["山田","有啊。你想踢足球吗？","Yǒu a. Nǐ xiǎng tī zúqiú ma?","Có chứ. Cậu muốn đá bóng à?"],["田中","是啊。足球场在哪儿？","Shì a. Zúqiúchǎng zài nǎr?","Ừ. Sân bóng ở đâu?"],["山田","在图书馆西边。图书馆南边还有一个篮球场。","Zài túshūguǎn xībian. Túshūguǎn nánbian hái yǒu yí ge lánqiúchǎng.","Ở phía tây thư viện. Phía nam thư viện còn có một sân bóng rổ."],["田中","那我们先去书店，然后去踢足球，好吗？","Nà wǒmen xiān qù shūdiàn, ránhòu qù tī zúqiú, hǎo ma?","Vậy mình đi hiệu sách trước, rồi đi đá bóng nhé?"],["山田","行。","Xíng.","Được."]]},{"t":"短文","c":[["","我们学校很大。","Wǒmen xuéxiào hěn dà.","Trường chúng tôi rất rộng."],["","学校里有教学楼、宿舍楼、图书馆、运动场、商店、书店，还有邮局、银行、医院。","Xuéxiào li yǒu jiàoxuélóu, sùshèlóu, túshūguǎn, yùndòngchǎng, shāngdiàn, shūdiàn, hái yǒu yóujú, yínháng, yīyuàn.","Trong trường có khu giảng đường, khu ký túc xá, thư viện, sân vận động, cửa hàng, hiệu sách, còn có bưu điện, ngân hàng, bệnh viện."],["","教学楼离宿舍楼不远，在宿舍楼东边。","Jiàoxuélóu lí sùshèlóu bù yuǎn, zài sùshèlóu dōngbian.","Khu giảng đường cách ký túc xá không xa, ở phía đông ký túc xá."],["","教学楼北边是图书馆。","Jiàoxuélóu běibian shì túshūguǎn.","Phía bắc khu giảng đường là thư viện."],["","运动场在图书馆西边。","Yùndòngchǎng zài túshūguǎn xībian.","Sân vận động ở phía tây thư viện."],["","商店和书店在宿舍楼西边，","Shāngdiàn hé shūdiàn zài sùshèlóu xībian,","Cửa hàng và hiệu sách ở phía tây ký túc xá,"],["","商店旁边是邮局和银行，","shāngdiàn pángbiān shì yóujú hé yínháng,","cạnh cửa hàng là bưu điện và ngân hàng,"],["","医院在银行西边，离银行有500米左右。","yīyuàn zài yínháng xībian, lí yínháng yǒu wǔbǎi mǐ zuǒyòu.","bệnh viện ở phía tây ngân hàng, cách ngân hàng khoảng 500 mét."]]}]},{"n":24,"ten":"","doan":[{"t":"会话","c":[["玛丽","山田，你每天早上做什么？","Shāntián, nǐ měi tiān zǎoshang zuò shénme?","Yamada, sáng nào cậu cũng làm gì?"],["山田","跑步，打太极拳。","Pǎobù, dǎ tàijíquán.","Chạy bộ, tập Thái cực quyền."],["玛丽","谁教太极拳？","Shéi jiāo tàijíquán?","Ai dạy Thái cực quyền?"],["山田","马老师。怎么，你想学吗？","Mǎ lǎoshī. Zěnme, nǐ xiǎng xué ma?","Thầy Mã. Sao, cậu muốn học à?"],["玛丽","想学。在哪儿报名？","Xiǎng xué. Zài nǎr bàomíng?","Muốn học. Đăng ký ở đâu?"],["山田","在马老师那儿。他每天早上六点半在小操场教我们，你明天去吧。","Zài Mǎ lǎoshī nàr. Tā měi tiān zǎoshang liù diǎn bàn zài xiǎo cāochǎng jiāo wǒmen, nǐ míngtiān qù ba.","Ở chỗ thầy Mã. Sáng nào thầy cũng dạy bọn tớ lúc 6 giờ rưỡi ở sân tập nhỏ, mai cậu đến nhé."],["玛丽","好。山田，学太极拳的人多吗？","Hǎo. Shāntián, xué tàijíquán de rén duō ma?","Được. Yamada, người học Thái cực quyền có đông không?"],["山田","不少。有老师，也有留学生。","Bù shǎo. Yǒu lǎoshī, yě yǒu liúxuéshēng.","Không ít đâu. Có giáo viên, cũng có lưu học sinh."],["玛丽","难学吗？","Nán xué ma?","Có khó học không?"],["山田","不难。","Bù nán.","Không khó."],["玛丽","好，明天早上小操场见。","Hǎo, míngtiān zǎoshang xiǎo cāochǎng jiàn.","Được, sáng mai gặp ở sân tập nhỏ nhé."],["山田","再见。","Zàijiàn.","Tạm biệt."]]},{"t":"短文","c":[["","玛丽很喜欢中国的书法，她觉得练书法很有意思。","Mǎlì hěn xǐhuan Zhōngguó de shūfǎ, tā juéde liàn shūfǎ hěn yǒu yìsi.","Mary rất thích thư pháp Trung Quốc, cô thấy luyện thư pháp rất thú vị."],["","每星期一和星期五下午有书法课。","Měi xīngqīyī hé xīngqīwǔ xiàwǔ yǒu shūfǎ kè.","Chiều thứ Hai và thứ Sáu hằng tuần có giờ thư pháp."],["","上课的时候，她认真听，认真练。","Shàng kè de shíhou, tā rènzhēn tīng, rènzhēn liàn.","Trong giờ học, cô chăm chú nghe, chăm chỉ luyện."],["","下课以后，她在宿舍继续练习。","Xià kè yǐhòu, tā zài sùshè jìxù liànxí.","Tan học, cô tiếp tục luyện ở ký túc xá."],["","她还常常看书法展览。","Tā hái chángcháng kàn shūfǎ zhǎnlǎn.","Cô còn thường đi xem triển lãm thư pháp."],["","她说：“练书法可以帮助我学习汉语，","Tā shuō: “Liàn shūfǎ kěyǐ bāngzhù wǒ xuéxí Hànyǔ,","Cô nói: “Luyện thư pháp có thể giúp tôi học tiếng Hán,"],["","帮助我学习汉字，还能帮助我了解中国文化。”","bāngzhù wǒ xuéxí Hànzì, hái néng bāngzhù wǒ liǎojiě Zhōngguó wénhuà.”","giúp tôi học chữ Hán, còn giúp tôi hiểu văn hoá Trung Quốc.”"]]}]},{"n":25,"ten":"","doan":[{"t":"会话","c":[["玛丽","马丁，你的发音真不错。","Mǎdīng, nǐ de fāyīn zhēn búcuò.","Martin, phát âm của cậu thật không tồi."],["马丁","是，我的汉字写得也很好。","Shì, wǒ de Hànzì xiě de yě hěn hǎo.","Đúng, chữ Hán của tớ viết cũng rất đẹp."],["玛丽","你课文念得怎么样？","Nǐ kèwén niàn de zěnmeyàng?","Cậu đọc bài khoá thế nào?"],["马丁","念得太流利了，听力就更没问题了。","Niàn de tài liúlì le, tīnglì jiù gèng méi wèntí le.","Đọc trôi chảy lắm, nghe thì càng không có vấn đề gì."],["玛丽","我看你汉语学得不好。","Wǒ kàn nǐ Hànyǔ xué de bù hǎo.","Tớ thấy cậu học tiếng Hán chưa giỏi."],["马丁","为什么？我什么地方说得不对？","Wèi shénme? Wǒ shénme dìfang shuō de bú duì?","Tại sao? Tớ nói sai chỗ nào?"],["玛丽","说得都很好。可是，中国人不这样说。","Shuō de dōu hěn hǎo. Kěshì, Zhōngguórén bú zhèyàng shuō.","Nói đều rất tốt. Nhưng người Trung Quốc không nói như vậy."],["马丁","是吗？那我应该怎么说？","Shì ma? Nà wǒ yīnggāi zěnme shuō?","Thế à? Vậy tớ nên nói thế nào?"],["玛丽","我说“你的发音真不错”，你应该说“哪里，哪里，还差得远呢”。","Wǒ shuō “nǐ de fāyīn zhēn búcuò”, nǐ yīnggāi shuō “nǎli, nǎli, hái chà de yuǎn ne”.","Tớ nói “phát âm của cậu thật không tồi”, cậu nên nói “đâu có, đâu có, còn kém xa lắm”."],["马丁","为什么要这样说？我觉得我的发音不错。","Wèi shénme yào zhèyàng shuō? Wǒ juéde wǒ de fāyīn búcuò.","Tại sao phải nói như vậy? Tớ thấy phát âm của tớ khá tốt mà."],["玛丽","对，你的发音很好，可是不能自己说自己好。","Duì, nǐ de fāyīn hěn hǎo, kěshì bù néng zìjǐ shuō zìjǐ hǎo.","Đúng, phát âm của cậu rất tốt, nhưng không được tự khen mình."],["马丁","是吗？","Shì ma?","Thế à?"]]},{"t":"短文","c":[["","早上，山田起得很早。","Zǎoshang, Shāntián qǐ de hěn zǎo.","Buổi sáng, Yamada dậy rất sớm."],["","他先去大操场跑步，然后到小操场打太极拳。","Tā xiān qù dà cāochǎng pǎobù, ránhòu dào xiǎo cāochǎng dǎ tàijíquán.","Cậu ấy ra sân lớn chạy bộ trước, sau đó đến sân nhỏ tập Thái cực quyền."],["","他很喜欢打太极拳，打得也不错。","Tā hěn xǐhuan dǎ tàijíquán, dǎ de yě búcuò.","Cậu ấy rất thích tập Thái cực quyền, tập cũng khá."],["","上星期他参加太极拳比赛，得了第二名。","Shàng xīngqī tā cānjiā tàijíquán bǐsài, dé le dì-èr míng.","Tuần trước cậu ấy tham gia thi Thái cực quyền, được giải nhì."],["","山田的老师说，他学得很认真，进步很快。","Shāntián de lǎoshī shuō, tā xué de hěn rènzhēn, jìnbù hěn kuài.","Thầy của Yamada nói, cậu ấy học rất chăm, tiến bộ rất nhanh."],["","山田说他还差得远，还要继续练，下次比赛要得第一名。","Shāntián shuō tā hái chà de yuǎn, hái yào jìxù liàn, xià cì bǐsài yào dé dì-yī míng.","Yamada nói mình còn kém xa, còn phải tiếp tục luyện, lần thi sau phải được giải nhất."]]}]}]},{"id":"fazhan-sc2","zh":"发展汉语初级综合 II","vi":"Phát triển Hán ngữ sơ cấp 2","bai":[{"n":1,"ten":"入乡随俗","doan":[{"t":"课文","c":[["","来中国半年多了，我已经渐渐地习惯了这里的生活。","Lái Zhōngguó bàn nián duō le, wǒ yǐjīng jiànjiàn de xíguàn le zhèlǐ de shēnghuó.","Đã đến Trung Quốc hơn nửa năm, tôi đã dần dần quen với cuộc sống ở đây rồi."],["","刚来中国的时候，最不习惯的是早上八点钟上课。","Gāng lái Zhōngguó de shíhou, zuì bù xíguàn de shì zǎoshang bā diǎnzhōng shàngkè.","Khi mới đến Trung Quốc, điều khó quen nhất là phải lên lớp lúc tám giờ sáng."],["","因为1我是个夜猫子2，喜欢晚睡晚起，所以经常迟到。","Yīnwèi wǒ shì gè yèmāozi, xǐhuān wǎn shuì wǎn qǐ, suǒyǐ jīngcháng chídào.","Vì tôi là người hay thức khuya, thích ngủ muộn dậy muộn, nên thường xuyên đến trễ."],["","你进教室的时候，别人正在上课呢，大家都看着你，真不好意思。","Nǐ jìn jiàoshì de shíhou, biérén zhèngzài shàngkè ne, dàjiā dōu kàn zhe nǐ, zhēn bù hǎoyìsi.","Khi bạn bước vào lớp, người ta đang học rồi, mọi người đều nhìn vào bạn, thật xấu hổ."],["","为了不迟到，我买了一个闹钟。","Wèile bù chídào, wǒ mǎi le yī gè nàozhōng.","Để không đến trễ, tôi đã mua một cái đồng hồ báo thức."],["","每天早上一到七点钟，它就大叫：\"懒虫，该起床了！懒虫，该起床了！\"","Měitiān zǎoshang yī dào qī diǎnzhōng, tā jiù dà jiào: \"Lǎnchóng, gāi qǐchuáng le! Lǎnchóng, gāi qǐchuáng le!\"","Mỗi sáng, vừa đến bảy giờ, nó liền kêu to: \"Đồ lười, dậy đi thôi! Đồ lười, dậy đi thôi!\""],["","虽然不好听，我还不能不感谢它。","Suīrán bù hǎo tīng, wǒ hái bù néng bù gǎnxiè tā.","Dù nghe không hay, nhưng tôi vẫn không thể không cảm ơn nó."],["","因为有了它，我现在已经很少迟到了。","Yīnwèi yǒu le tā, wǒ xiànzài yǐjīng hěn shǎo chídào le.","Vì có nó, giờ đây tôi đã rất ít khi đến trễ rồi."],["","我还有一件不习惯的事，就是打招呼。","Wǒ hái yǒu yī jiàn bù xíguàn de shì, jiù shì dǎ zhāohu.","Tôi còn có một điều nữa chưa quen, đó là cách chào hỏi."],["","有些中国人和我见面不是问好，而是问一些奇怪的问题。","Yǒuxiē Zhōngguórén hé wǒ jiànmiàn bú shì wènhǎo, ér shì wèn yīxiē qíguài de wèntí.","Một số người Trung Quốc khi gặp tôi không phải là chào hỏi, mà là hỏi những câu hỏi kỳ lạ."],["","下面就是今天早上我和邻居的对话：","Xiàmiàn jiù shì jīntiān zǎoshang wǒ hé línjū de duìhuà:","Dưới đây là cuộc đối thoại giữa tôi và người hàng xóm sáng nay:"],["邻居","\"早！\"","\"Zǎo!\"","\"Chào!\""],["我","\"早上好！\"","\"Zǎoshang hǎo!\"","\"Chào buổi sáng!\""],["邻居","\"吃了吗？\"","\"Chī le ma?\"","\"Ăn chưa?\""],["我","\"吃了。\"","\"Chī le.\"","\"Ăn rồi.\""],["邻居","\"去上课呀？\"","\"Qù shàngkè ya?\"","\"Đi học à?\""],["我","\"是。\"","\"Shì.\"","\"Vâng.\""],["邻居","\"外面正下着雨呢，带伞了吗？\"","\"Wàimiàn zhèng xià zhe yǔ ne, dài sǎn le ma?\"","\"Bên ngoài đang mưa đó, mang ô chưa?\""],["我","\"谢谢，我带着呢。\"","\"Xièxie, wǒ dài zhe ne.\"","\"Cảm ơn, mang rồi.\""],["","这要是在半年以前，有人这样跟我打招呼，我肯定生气了。","Zhè yàoshi zài bàn nián yǐqián, yǒurén zhèyàng gēn wǒ dǎ zhāohu, wǒ kěndìng shēngqì le.","Nếu là nửa năm trước, có người chào hỏi tôi như vậy, chắc tôi đã tức giận rồi."],["","可是，现在我却3觉得挺亲切的，因为我知道，他们跟熟人才这么打招呼。","Kěshì, xiànzài wǒ què juéde tǐng qīnqiè de, yīnwèi wǒ zhīdào, tāmen gēn shúrén cái zhème dǎ zhāohu.","Nhưng bây giờ tôi lại cảm thấy khá thân thiết, vì tôi biết rằng họ chỉ chào như vậy với người quen."],["","要是你不想回答他们的问题，问好就可以了。","Yàoshi nǐ bù xiǎng huídá tāmen de wèntí, wènhǎo jiù kěyǐ le.","Nếu bạn không muốn trả lời câu hỏi của họ, chỉ cần chào hỏi bình thường là được."],["","中国有一个成语叫\"入乡随俗\"，意思是：到了一个新的地方，就要适应那里的风俗习惯。","Zhōngguó yǒu yī gè chéngyǔ jiào \"rù xiāng suí sú\", yìsi shì: dào le yī gè xīn de dìfang, jiù yào shìyìng nàlǐ de fēngsú xíguàn.","Trung Quốc có một thành ngữ là \"nhập gia tùy tục\", nghĩa là: đến một nơi mới thì phải thích nghi với phong tục tập quán nơi đó."]]}]},{"n":2,"ten":"儿子要回家","doan":[{"t":"课文","c":[["医生朋友","“听说你儿子大学毕业了，恭喜恭喜！”","“Tīngshuō nǐ érzi dàxué bìyè le, gōngxǐ gōngxǐ!”","“Nghe nói con trai chị tốt nghiệp đại học rồi, chúc mừng chúc mừng!”"],["妈妈","“你别恭喜我，我正为这件事担心呢，你快帮帮我吧。”","“Nǐ bié gōngxǐ wǒ, wǒ zhèng wèi zhè jiàn shì dānxīn ne, nǐ kuài bāngbang wǒ ba.”","“Anh đừng chúc mừng tôi, tôi đang lo lắng vì chuyện này đây, anh mau giúp tôi với.”"],["医生朋友","“儿子要回家了，是好事啊，你为什么这么担心呢？我能给你什么帮助呢？”","“Érzi yào huíjiā le, shì hǎoshì a, nǐ wèi shénme zhème dānxīn ne? Wǒ néng gěi nǐ shénme bāngzhù ne?”","“Con trai sắp về nhà là chuyện tốt mà, sao chị lại lo lắng thế? Tôi có thể giúp chị việc gì?”"],["妈妈","“当然，因为你是医生啊。”","“Dāngrán, yīnwèi nǐ shì yīshēng a.”","“Đương nhiên rồi, vì anh là bác sĩ mà.”"],["医生朋友","“这件事跟我是医生有什么关系吗？”","“Zhè jiàn shì gēn wǒ shì yīshēng yǒu shénme guānxi ma?”","“Chuyện này thì liên quan gì đến việc tôi là bác sĩ?”"],["妈妈","“当然有关系。儿子从上大学到现在，从来没打扫过房间，我害怕他带着病毒回家。”","“Dāngrán yǒu guānxi. Érzi cóng shàng dàxué dào xiànzài, cónglái méi dǎsǎo guo fángjiān, wǒ hàipà tā dài zhe bìngdú huíjiā.”","“Đương nhiên là có liên quan. Từ lúc vào đại học đến giờ, thằng bé chưa bao giờ dọn phòng, tôi sợ nó mang virus về nhà.”"],["医生朋友","“哦，我明白了。那请您给我介绍一下他的宿舍吧。”","“Ò, wǒ míngbai le. Nà qǐng nín gěi wǒ jièshào yíxià tā de sùshè ba.”","“Ồ, tôi hiểu rồi. Vậy mời chị giới thiệu cho tôi về ký túc xá của cậu ấy đi.”"],["妈妈","“房间不大不小。靠墙摆着一张床，床下放着一堆脏衣服。桌子上面放着一台电脑、许多旧书、几张音乐CD、两个啤酒瓶子。对了1，书上还放着一只鞋。房间里乱七八糟的，太脏了。”","“Fángjiān bú dà bù xiǎo. Kào qiáng bǎi zhe yì zhāng chuáng, chuáng xià fàng zhe yì duī zāng yīfu. Zhuōzi shàngmiàn fàng zhe yì tái diànnǎo, xǔduō jiù shū, jǐ zhāng yīnyuè CD, liǎng ge píjiǔ píngzi. Duì le, shū shang hái fàng zhe yì zhī xié. Fángjiān lǐ luànqībāzāo de, tài zāng le.”","“Phòng không to không nhỏ. Kê sát tường là một cái giường, dưới gầm giường có một đống quần áo bẩn. Trên bàn đặt một cái máy tính, nhiều sách cũ, mấy đĩa CD nhạc, hai cái chai bia. À phải rồi, trên sách còn để một chiếc giày. Trong phòng bừa bộn lộn xộn, bẩn lắm.”"],["医生朋友","“墙角放着一个垃圾箱，是吧？”","“Qiángjiǎo fàng zhe yí ge lājīxiāng, shì ba?”","“Ở góc tường có đặt một thùng rác, đúng không?”"],["妈妈","“对呀，里面放着空食品袋、空酸奶盒、脏袜子、废纸什么的2。”","“Duì ya, lǐmiàn fàng zhe kōng shípǐn dài, kōng suānnǎi hé, zāng wàzi, fèizhǐ shénme de.”","“Đúng vậy, bên trong có túi đồ ăn rỗng, hộp sữa chua rỗng, tất bẩn, giấy lộn v.v.”"],["医生朋友","“屋子里有衣柜吗？”","“Wūzi lǐ yǒu yīguì ma?”","“Trong phòng có tủ quần áo không?”"],["妈妈","“有，不过衣柜里没挂着衣服，却放着足球、篮球什么的，衣服都在地上堆着呢……”","“Yǒu, búguò yīguì lǐ méi guà zhe yīfu, què fàng zhe zúqiú, lánqiú shénme de, yīfu dōu zài dì shang duī zhe ne……”","“Có, có điều trong tủ không treo quần áo mà lại để bóng đá, bóng rổ v.v., còn quần áo thì chất đống dưới đất đấy……”"],["医生朋友","“他自己每天洗碗吗？”","“Tā zìjǐ měitiān xǐ wǎn ma?”","“Cậu ấy tự rửa bát mỗi ngày không?”"],["妈妈","“用过的盘子和碗，他一个星期才洗一次。”","“Yòng guo de pánzi hé wǎn, tā yí ge xīngqī cái xǐ yí cì.”","“Đĩa và bát đã dùng, một tuần nó mới rửa một lần.”"],["医生朋友","“你们以前没发现这个问题吗？”","“Nǐmen yǐqián méi fāxiàn zhège wèntí ma?”","“Trước đây các chị không phát hiện ra vấn đề này sao?”"],["妈妈","“刚上大学的时候，他说要自由，不让我们去他的宿舍。我们是最近才发现了这个问题。”","“Gāng shàng dàxué de shíhou, tā shuō yào zìyóu, bú ràng wǒmen qù tā de sùshè. Wǒmen shì zuìjìn cái fāxiàn le zhège wèntí.”","“Lúc mới vào đại học, nó nói muốn tự do, không cho chúng tôi đến ký túc xá của nó. Mãi gần đây chúng tôi mới phát hiện ra vấn đề này.”"],["医生朋友","“他真是太自由了！你儿子的宿舍里一定有不少病毒。你们真应该小心点儿，最好3给他的东西消消毒。对了，你儿子毕业以后想做什么工作？”","“Tā zhēn shì tài zìyóu le! Nǐ érzi de sùshè lǐ yídìng yǒu bù shǎo bìngdú. Nǐmen zhēn yīnggāi xiǎoxīn diǎnr, zuìhǎo gěi tā de dōngxi xiāoxiao dú. Duì le, nǐ érzi bìyè yǐhòu xiǎng zuò shénme gōngzuò?”","“Cậu ấy đúng là quá tự do! Trong ký túc xá của con trai chị chắc chắn có không ít virus. Các chị thật sự nên cẩn thận hơn, tốt nhất là khử trùng đồ đạc của cậu ấy. À phải rồi, sau khi tốt nghiệp con trai chị muốn làm công việc gì?”"],["妈妈","“他想做和环境保护有关系的工作。”","“Tā xiǎng zuò hé huánjìng bǎohù yǒu guānxi de gōngzuò.”","“Nó muốn làm công việc liên quan đến bảo vệ môi trường.”"]]}]},{"n":3,"ten":"卖辣椒的女孩儿","doan":[{"t":"课文","c":[["","有个女孩儿到市场去卖辣椒。","Yǒu ge nǚháir dào shìchǎng qù mài làjiāo.","Có một cô bé ra chợ bán ớt."],["","第一天，因为没有经验，她只带了一篮子辣椒。","Dì-yī tiān, yīnwèi méiyǒu jīngyàn, tā zhǐ dài le yì lánzi làjiāo.","Ngày thứ nhất, vì không có kinh nghiệm, cô chỉ mang theo một rổ ớt."],["","她的辣椒红红的，又好看又新鲜，","Tā de làjiāo hónghóng de, yòu hǎokàn yòu xīnxiān,","Ớt của cô đỏ au, vừa đẹp vừa tươi,"],["","女孩儿相信自己的辣椒一定好卖。","Nǚháir xiāngxìn zìjǐ de làjiāo yídìng hǎo mài.","cô bé tin rằng ớt của mình chắc chắn sẽ dễ bán."],["","第一个顾客走过来问：“这辣椒是辣的还是甜的？”","Dì-yī ge gùkè zǒu guòlai wèn: “Zhè làjiāo shì là de háishi tián de?”","Người khách đầu tiên đi tới hỏi: “Ớt này cay hay ngọt?”"],["","女孩儿站起来热情地回答：“辣椒当然是辣的了。”","Nǚháir zhàn qǐlai rèqíng de huídá: “Làjiāo dāngrán shì là de le.”","Cô bé đứng dậy nhiệt tình trả lời: “Ớt thì đương nhiên là cay rồi.”"],["","顾客摇摇头说：“我是上海人，喜欢吃甜的。”","Gùkè yáoyao tóu shuō: “Wǒ shì Shànghǎi rén, xǐhuan chī tián de.”","Người khách lắc đầu nói: “Tôi là người Thượng Hải, thích ăn ngọt.”"],["","第二位顾客走过来问：“这辣椒是辣的还是甜的？”","Dì-èr wèi gùkè zǒu guòlai wèn: “Zhè làjiāo shì là de háishi tián de?”","Vị khách thứ hai đi tới hỏi: “Ớt này cay hay ngọt?”"],["","小姑娘赶紧回答：“甜的。”","Xiǎo gūniang gǎnjǐn huídá: “Tián de.”","Cô bé vội trả lời: “Ngọt ạ.”"],["","顾客又摇了摇头说：“我是四川人，不怕1辣，就怕不辣。不辣的就不能叫辣椒。”","Gùkè yòu yáo le yáo tóu shuō: “Wǒ shì Sìchuān rén, bú pà là, jiù pà bú là. Bú là de jiù bù néng jiào làjiāo.”","Người khách lại lắc đầu nói: “Tôi là người Tứ Xuyên, không sợ cay, chỉ sợ không cay. Không cay thì không gọi là ớt được.”"],["","这一天，小姑娘一个辣椒都没卖出去，她只好2把辣椒拿回家去。","Zhè yì tiān, xiǎo gūniang yí ge làjiāo dōu méi mài chūqu, tā zhǐhǎo bǎ làjiāo ná huí jiā qu.","Hôm ấy, cô bé chẳng bán được quả ớt nào, đành phải mang ớt về nhà."],["","女孩儿很难过，她怎么也想不通3：这么好的辣椒，为什么会卖不出去呢？","Nǚháir hěn nánguò, tā zěnme yě xiǎng bu tōng: zhème hǎo de làjiāo, wèi shénme huì mài bu chūqu ne?","Cô bé rất buồn, nghĩ mãi không hiểu: ớt ngon thế này, sao lại không bán được nhỉ?"],["","第二天，她带了两篮子辣椒去市场卖，一篮子是辣的，一篮子是甜的。","Dì-èr tiān, tā dài le liǎng lánzi làjiāo qù shìchǎng mài, yì lánzi shì là de, yì lánzi shì tián de.","Ngày thứ hai, cô mang hai rổ ớt ra chợ bán, một rổ cay, một rổ ngọt."],["","上海人买了甜的，四川人买了辣的。","Shànghǎi rén mǎi le tián de, Sìchuān rén mǎi le là de.","Người Thượng Hải mua ớt ngọt, người Tứ Xuyên mua ớt cay."],["","一个北京人走过来问：“这辣椒是什么味道的？”","Yí ge Běijīng rén zǒu guòlai wèn: “Zhè làjiāo shì shénme wèidao de?”","Một người Bắc Kinh đi tới hỏi: “Ớt này vị gì?”"],["","小姑娘回答：“左边的篮子里是辣的，右边的篮子里是甜的。”","Xiǎo gūniang huídá: “Zuǒbian de lánzi li shì là de, yòubian de lánzi li shì tián de.”","Cô bé trả lời: “Rổ bên trái là ớt cay, rổ bên phải là ớt ngọt.”"],["","顾客摇了摇头说：“怎么没有既不辣也不甜的青椒呢？”","Gùkè yáo le yáo tóu shuō: “Zěnme méiyǒu jì bú là yě bù tián de qīngjiāo ne?”","Người khách lắc đầu nói: “Sao không có ớt xanh vừa không cay vừa không ngọt nhỉ?”"],["","第三天，她带了三篮子辣椒去卖，一篮子甜的，一篮子辣的，一篮子既不辣又不甜的。","Dì-sān tiān, tā dài le sān lánzi làjiāo qù mài, yì lánzi tián de, yì lánzi là de, yì lánzi jì bú là yòu bù tián de.","Ngày thứ ba, cô mang ba rổ ớt đi bán: một rổ ngọt, một rổ cay, một rổ không cay cũng không ngọt."],["","上海人、四川人、北京人买了不同味道的辣椒。","Shànghǎi rén, Sìchuān rén, Běijīng rén mǎi le bù tóng wèidao de làjiāo.","Người Thượng Hải, người Tứ Xuyên, người Bắc Kinh đều mua được ớt có vị mình thích."],["","一个山东人走过来问：“这辣椒是什么味道的？”","Yí ge Shāndōng rén zǒu guòlai wèn: “Zhè làjiāo shì shénme wèidao de?”","Một người Sơn Đông đi tới hỏi: “Ớt này vị gì?”"],["","小姑娘回答：“左边的篮子里是甜的，右边的篮子里是辣的，中间的是既不辣又不甜的。”","Xiǎo gūniang huídá: “Zuǒbian de lánzi li shì tián de, yòubian de lánzi li shì là de, zhōngjiān de shì jì bú là yòu bù tián de.”","Cô bé trả lời: “Rổ bên trái là ớt ngọt, rổ bên phải là ớt cay, rổ ở giữa là loại không cay cũng không ngọt.”"],["","顾客摇了摇头说：“怎么没有又辣又甜又香的呢？”","Gùkè yáo le yáo tóu shuō: “Zěnme méiyǒu yòu là yòu tián yòu xiāng de ne?”","Người khách lắc đầu nói: “Sao không có loại vừa cay vừa ngọt vừa thơm nhỉ?”"],["","第四天，她带了四篮子辣椒去卖，一篮子辣的，一篮子甜的，一篮子既不辣又不甜的，一篮子又辣又甜又香的。","Dì-sì tiān, tā dài le sì lánzi làjiāo qù mài, yì lánzi là de, yì lánzi tián de, yì lánzi jì bú là yòu bù tián de, yì lánzi yòu là yòu tián yòu xiāng de.","Ngày thứ tư, cô mang bốn rổ ớt đi bán: một rổ cay, một rổ ngọt, một rổ không cay cũng không ngọt, một rổ vừa cay vừa ngọt vừa thơm."],["","这一天，奇迹发生了，小姑娘把所有4的辣椒都卖出去了。","Zhè yì tiān, qíjì fāshēng le, xiǎo gūniang bǎ suǒyǒu de làjiāo dōu mài chūqu le.","Hôm ấy, phép màu đã xảy ra: cô bé bán hết sạch tất cả số ớt."]]}]},{"n":4,"ten":"我和中国有个约会","doan":[{"t":"课文","c":[["","我叫马丁，是从德国来的。","Wǒ jiào Mǎdīng, shì cóng Déguó lái de.","Tôi tên là Martin, đến từ nước Đức."],["","我和中国的缘分是从六岁开始的。","Wǒ hé Zhōngguó de yuánfèn shì cóng liù suì kāishǐ de.","Duyên phận của tôi với Trung Quốc bắt đầu từ năm sáu tuổi."],["","那时正在流行成龙1的电影，我就开始喜欢中国功夫了。","Nà shí zhèngzài liúxíng Chéng Lóng de diànyǐng, wǒ jiù kāishǐ xǐhuan Zhōngguó gōngfu le.","Hồi đó phim của Thành Long đang thịnh hành, tôi bắt đầu thích kung fu Trung Quốc."],["","我有一个中国老师，他不但教我中国功夫，而且还教我很多做人的道理。","Wǒ yǒu yí ge Zhōngguó lǎoshī, tā búdàn jiāo wǒ Zhōngguó gōngfu, érqiě hái jiāo wǒ hěn duō zuòrén de dàolǐ.","Tôi có một thầy giáo người Trung Quốc, thầy không những dạy tôi kung fu mà còn dạy tôi nhiều đạo lý làm người."],["","后来，我又开始学习汉语。","Hòulái, wǒ yòu kāishǐ xuéxí Hànyǔ.","Sau đó, tôi lại bắt đầu học tiếng Hán."],["","有人对我说：“学汉语没用，既不能挣大钱，也没什么出息。”","Yǒu rén duì wǒ shuō: “Xué Hànyǔ méi yòng, jì bù néng zhèng dà qián, yě méi shénme chūxi.”","Có người nói với tôi: “Học tiếng Hán vô dụng, vừa không kiếm được nhiều tiền, cũng chẳng có tiền đồ gì.”"],["","但是我还是选择了汉语，而且一点儿也不后悔。","Dànshì wǒ háishi xuǎnzé le Hànyǔ, érqiě yìdiǎnr yě bù hòuhuǐ.","Nhưng tôi vẫn chọn tiếng Hán, hơn nữa chẳng hối hận chút nào."],["","我交了很多中国朋友，我们一起吃中国菜，喝中国茶，谈中国文化，去中国旅行。","Wǒ jiāo le hěn duō Zhōngguó péngyou, wǒmen yìqǐ chī Zhōngguó cài, hē Zhōngguó chá, tán Zhōngguó wénhuà, qù Zhōngguó lǚxíng.","Tôi kết bạn với nhiều người Trung Quốc, chúng tôi cùng ăn món Trung Quốc, uống trà Trung Quốc, bàn về văn hóa Trung Quốc, đi du lịch Trung Quốc."],["","现在，不但我喜欢中国，我的家人和朋友也都喜欢中国。","Xiànzài, búdàn wǒ xǐhuan Zhōngguó, wǒ de jiārén hé péngyou yě dōu xǐhuan Zhōngguó.","Bây giờ, không chỉ tôi thích Trung Quốc, gia đình và bạn bè tôi cũng đều thích Trung Quốc."],["","在我的生活里，到处都能找到中国元素：","Zài wǒ de shēnghuó li, dàochù dōu néng zhǎodào Zhōngguó yuánsù:","Trong cuộc sống của tôi, chỗ nào cũng tìm thấy yếu tố Trung Quốc:"],["","我家的墙上挂着中国画，书架上放着中文书，我身上穿着唐装。","Wǒ jiā de qiáng shang guà zhe Zhōngguó huà, shūjià shang fàng zhe Zhōngwén shū, wǒ shēn shang chuān zhe tángzhuāng.","trên tường nhà tôi treo tranh Trung Quốc, trên giá sách để sách tiếng Trung, trên người tôi mặc áo kiểu Đường."],["","一年前我来到中国留学，学费是我利用假期打工挣的。","Yì nián qián wǒ láidào Zhōngguó liúxué, xuéfèi shì wǒ lìyòng jiàqī dǎgōng zhèng de.","Một năm trước tôi sang Trung Quốc du học, học phí là do tôi tranh thủ kỳ nghỉ đi làm thêm kiếm được."],["","在中国，能经常和中国人用汉语聊天儿，因此2我的汉语进步得很快，说得越来越好。","Zài Zhōngguó, néng jīngcháng hé Zhōngguórén yòng Hànyǔ liáotiānr, yīncǐ wǒ de Hànyǔ jìnbù de hěn kuài, shuō de yuèláiyuè hǎo.","Ở Trung Quốc, tôi thường được trò chuyện với người Trung Quốc bằng tiếng Hán, vì vậy tiếng Hán của tôi tiến bộ rất nhanh, nói ngày càng giỏi."],["","现在，我快毕业了，是得认真想一想工作的事了。","Xiànzài, wǒ kuài bìyè le, shì děi rènzhēn xiǎng yi xiǎng gōngzuò de shì le.","Bây giờ tôi sắp tốt nghiệp, đúng là phải nghiêm túc nghĩ về chuyện công việc rồi."],["","做什么工作好呢？","Zuò shénme gōngzuò hǎo ne?","Làm nghề gì thì tốt đây?"],["","当中国饭馆的厨师挺好，这样我就可以每天吃好吃的“宫保鸡丁3”、“麻婆豆腐4”了。","Dāng Zhōngguó fànguǎn de chúshī tǐng hǎo, zhèyàng wǒ jiù kěyǐ měi tiān chī hǎochī de “gōngbǎo jīdīng”, “Mápó dòufu” le.","Làm đầu bếp ở nhà hàng Trung Quốc cũng hay, như vậy ngày nào tôi cũng được ăn món “gà Kung Pao”, “đậu phụ Tứ Xuyên” ngon lành."],["","这些菜名，一想起来我就要流口水。","Zhèxiē càimíng, yì xiǎng qǐlai wǒ jiù yào liú kǒushuǐ.","Những tên món này, cứ nghĩ đến là tôi chảy nước miếng."],["","给中国人当导游也不错，我可以每天说汉语，还可以交很多中国朋友。","Gěi Zhōngguórén dāng dǎoyóu yě búcuò, wǒ kěyǐ měi tiān shuō Hànyǔ, hái kěyǐ jiāo hěn duō Zhōngguó péngyou.","Làm hướng dẫn viên cho người Trung Quốc cũng không tệ, tôi được nói tiếng Hán mỗi ngày, lại có thể kết bạn với nhiều người Trung Quốc."],["","虽然当厨师、当导游都不能挣大钱，但是我都喜欢。","Suīrán dāng chúshī, dāng dǎoyóu dōu bù néng zhèng dà qián, dànshì wǒ dōu xǐhuan.","Tuy làm đầu bếp hay làm hướng dẫn viên đều không kiếm được nhiều tiền, nhưng tôi đều thích."],["","其实，到现在我还没想好以后做什么工作呢，","Qíshí, dào xiànzài wǒ hái méi xiǎnghǎo yǐhòu zuò shénme gōngzuò ne,","Thật ra, đến giờ tôi vẫn chưa nghĩ xong sau này sẽ làm nghề gì,"],["","但是，我知道我的工作一定和中国有关系，因为，我和中国有个约会。","dànshì, wǒ zhīdào wǒ de gōngzuò yídìng hé Zhōngguó yǒu guānxi, yīnwèi, wǒ hé Zhōngguó yǒu ge yuēhuì.","nhưng tôi biết công việc của tôi nhất định sẽ liên quan đến Trung Quốc, bởi vì tôi có một cuộc hẹn với Trung Quốc."]]}]},{"n":5,"ten":"为什么我一个人站着吃","doan":[{"t":"课文","c":[["","小王娶1了一个漂亮的美国姑娘，名字叫黛比。","Xiǎo Wáng qǔ le yí ge piàoliang de Měiguó gūniang, míngzi jiào Dàibǐ.","Tiểu Vương cưới một cô gái Mỹ xinh đẹp, tên là Debby."],["","今年春节，小王带着她回到了北京。","Jīnnián Chūnjié, Xiǎo Wáng dài zhe tā huídào le Běijīng.","Tết năm nay, Tiểu Vương đưa cô ấy về Bắc Kinh."],["","小王的父母特别喜欢这个“洋2媳妇”，每天都给她做好吃的饭菜。","Xiǎo Wáng de fùmǔ tèbié xǐhuan zhège “yáng xífu”, měi tiān dōu gěi tā zuò hǎochī de fàncài.","Bố mẹ Tiểu Vương đặc biệt thích cô “con dâu Tây” này, ngày nào cũng nấu món ngon cho cô."],["","小王每天陪着黛比到处参观。","Xiǎo Wáng měi tiān péi zhe Dàibǐ dàochù cānguān.","Ngày nào Tiểu Vương cũng đưa Debby đi tham quan khắp nơi."],["","游览故宫的时候，黛比说：“中国的皇帝真奇怪，娶那么多的妻子，多麻烦！”","Yóulǎn Gùgōng de shíhou, Dàibǐ shuō: “Zhōngguó de huángdì zhēn qíguài, qǔ nàme duō de qīzi, duō máfan!”","Khi tham quan Cố Cung, Debby nói: “Hoàng đế Trung Quốc thật kỳ lạ, cưới nhiều vợ như thế, phiền biết bao!”"],["","小王开玩笑3说：“要是一百年前你来到中国，中国的皇帝选中4了你，你不愿意，怎么办？”","Xiǎo Wáng kāi wánxiào shuō: “Yàoshi yìbǎi nián qián nǐ láidào Zhōngguó, Zhōngguó de huángdì xuǎnzhòng le nǐ, nǐ bú yuànyì, zěnme bàn?”","Tiểu Vương nói đùa: “Nếu một trăm năm trước em đến Trung Quốc, hoàng đế chọn trúng em, em không muốn thì làm sao?”"],["","黛比笑着说：“那好办。要是我不愿意，就回美国去。”","Dàibǐ xiào zhe shuō: “Nà hǎo bàn. Yàoshi wǒ bú yuànyì, jiù huí Měiguó qu.”","Debby cười nói: “Thế thì dễ thôi. Nếu em không muốn thì về Mỹ.”"],["","“那你可就回不去了，这个大院子里的女人是没有自由的。","“Nà nǐ kě jiù huí bu qù le, zhège dà yuànzi li de nǚrén shì méiyǒu zìyóu de.","“Thế thì em không về được đâu, phụ nữ trong cái sân lớn này không có tự do."],["","不过，现在你什么也不用怕，中国很尊重妇女，女人结婚以后都不用改姓。”","Búguò, xiànzài nǐ shénme yě búyòng pà, Zhōngguó hěn zūnzhòng fùnǚ, nǚrén jiéhūn yǐhòu dōu búyòng gǎi xìng.”","Có điều, bây giờ em chẳng cần sợ gì cả, Trung Quốc rất tôn trọng phụ nữ, phụ nữ kết hôn xong đều không phải đổi họ.”"],["","第二天早晨，小王全家吃中国式早餐——豆浆、油条。","Dì-èr tiān zǎochen, Xiǎo Wáng quán jiā chī Zhōngguó shì zǎocān — dòujiāng, yóutiáo.","Sáng hôm sau, cả nhà Tiểu Vương ăn bữa sáng kiểu Trung Quốc: sữa đậu nành, bánh quẩy."],["","黛比第一次吃油条，喜欢得不得了5，拿起油条大口大口地吃起来。","Dàibǐ dì-yī cì chī yóutiáo, xǐhuan de bùdéliǎo, ná qǐ yóutiáo dà kǒu dà kǒu de chī qǐlai.","Debby lần đầu ăn bánh quẩy, thích vô cùng, cầm bánh quẩy lên cắn từng miếng to."],["","小王怕她噎着，就指着豆浆碗说：“蘸着吃。”","Xiǎo Wáng pà tā yē zhe, jiù zhǐ zhe dòujiāng wǎn shuō: “Zhàn zhe chī.”","Tiểu Vương sợ cô bị nghẹn, liền chỉ vào bát sữa đậu nành nói: “Chấm mà ăn.”"],["","黛比吃惊地看着小王，不懂他说的是什么意思。","Dàibǐ chījīng de kàn zhe Xiǎo Wáng, bù dǒng tā shuō de shì shénme yìsi.","Debby ngạc nhiên nhìn Tiểu Vương, không hiểu anh nói gì."],["","婆婆也笑着说：“蘸着吃。”","Pópo yě xiào zhe shuō: “Zhàn zhe chī.”","Mẹ chồng cũng cười nói: “Chấm mà ăn.”"],["","公公也说：“对，蘸着吃。”","Gōnggong yě shuō: “Duì, zhàn zhe chī.”","Bố chồng cũng nói: “Đúng, chấm mà ăn.”"],["","小王的弟弟也说：“是啊，应该蘸着吃。”","Xiǎo Wáng de dìdi yě shuō: “Shì a, yīnggāi zhàn zhe chī.”","Em trai Tiểu Vương cũng nói: “Phải đó, nên chấm mà ăn.”"],["","黛比在美国学过汉语，听力不错，所以跟小王家人交流没问题，","Dàibǐ zài Měiguó xué guo Hànyǔ, tīnglì búcuò, suǒyǐ gēn Xiǎo Wáng jiārén jiāoliú méi wèntí,","Debby từng học tiếng Hán ở Mỹ, nghe khá tốt, nên giao tiếp với nhà Tiểu Vương không có vấn đề gì,"],["","可是现在她却不明白大家的意思了。","kěshì xiànzài tā què bù míngbai dàjiā de yìsi le.","thế mà bây giờ cô lại không hiểu mọi người muốn nói gì."],["","“蘸着吃，好吃。”小王又说了一遍。","“Zhàn zhe chī, hǎochī.” Xiǎo Wáng yòu shuō le yí biàn.","“Chấm mà ăn, ngon lắm.” Tiểu Vương nói lại lần nữa."],["","黛比拿着油条慢慢地站了起来，生气地对小王说：","Dàibǐ ná zhe yóutiáo mànmàn de zhàn le qǐlai, shēngqì de duì Xiǎo Wáng shuō:","Debby cầm bánh quẩy từ từ đứng dậy, giận dỗi nói với Tiểu Vương:"],["","“你，你还说中国尊重妇女呢6，骗人。","“Nǐ, nǐ hái shuō Zhōngguó zūnzhòng fùnǚ ne, piàn rén.","“Anh, anh còn nói Trung Quốc tôn trọng phụ nữ, lừa người."],["","你们都坐着吃，为什么我一个人站着吃？”","Nǐmen dōu zuò zhe chī, wèi shénme wǒ yí ge rén zhàn zhe chī?”","Mọi người đều ngồi ăn, sao một mình em phải đứng ăn?”"]]}]}]},{"id":"fazhan-tc1","zh":"发展汉语中级综合 I","vi":"Phát triển Hán ngữ trung cấp 1","bai":[{"n":1,"ten":"北京的四季","doan":[{"t":"课文","c":[["开篇","永远不能忘记的是北京，因为我在那里住得太久了，仿佛树生了根一样。","Yǒngyuǎn bù néng wàngjì de shì Běijīng, yīnwèi wǒ zài nàlǐ zhù de tài jiǔ le, fǎngfú shù shēng le gēn yíyàng.","Điều tôi mãi mãi không thể quên là Bắc Kinh, vì tôi đã sống ở đó quá lâu, như thể cây đã bén rễ vậy."],["开篇","从童年到少女又到妇人，一半的人生都是在那里度过的。","Cóng tóngnián dào shàonǚ yòu dào fùrén, yíbàn de rénshēng dōu shì zài nàlǐ dùguò de.","Từ thuở thơ ấu đến thiếu nữ rồi đến người phụ nữ trưởng thành, một nửa cuộc đời tôi đã trôi qua ở nơi ấy."],["开篇","我是多么熟悉那里的每个季节啊！","Wǒ shì duōme shúxī nàlǐ de měi gè jìjié a!","Tôi quen thuộc biết bao với từng mùa ở nơi đó!"],["春","春天，人们纷纷来到西山，争着往山上爬，看谁先爬上那个最高的山头。","Chūntiān, rénmen fēnfēn láidào Xīshān, zhēngzhe wǎng shān shàng pá, kàn shéi xiān pá shàng nàge zuì gāo de shāntóu.","Mùa xuân, người ta nườm nượp kéo đến Tây Sơn, tranh nhau leo lên núi, xem ai leo lên đỉnh cao nhất trước."],["春","春天先看牡丹花，接着就是芍药花，北京的春天多么美丽呀！","Chūntiān xiān kàn mǔdānhuā, jiēzhe jiù shì sháoyàohuā, Běijīng de chūntiān duōme měilì ya!","Xuân đến trước hết là ngắm hoa mẫu đơn, tiếp theo là hoa thược dược; mùa xuân Bắc Kinh đẹp biết bao!"],["春","然而，美丽的花儿不怕雨，却怕风，有时一夜大风，就把花儿吹得不成样子了，","Rán’ér, měilì de huār bú pà yǔ, què pà fēng, yǒushí yí yè dà fēng, jiù bǎ huār chuī de bùchéng yàngzi le,","Thế nhưng, những đóa hoa đẹp không sợ mưa mà sợ gió; có khi một đêm gió lớn đã thổi hoa tơi tả, không còn ra hình dạng,"],["春","几阵大风就送走了春天，北京的春天又是多么短暂啊！","jǐ zhèn dàfēng jiù sòngzǒu le chūntiān, Běijīng de chūntiān yòu shì duōme duǎnzàn a!","vài đợt gió lớn là tiễn mùa xuân đi mất; mùa xuân Bắc Kinh lại ngắn ngủi biết bao!"],["夏","许多夏季的黄昏，喝一杯茉莉花茶，看一本心爱的书，听着蝉的叫声，享受安静。","Xǔduō xiàjì de huánghūn, hē yì bēi mòlìhuāchá, kàn yì běn xīn’ài de shū, tīngzhe chán de jiàoshēng, xiǎngshòu ānjìng.","Bao buổi chiều tà mùa hè, nhấp một chén trà hoa nhài, đọc một cuốn sách yêu thích, nghe tiếng ve kêu, tận hưởng sự yên tĩnh."],["夏","最难忘的是夏季的暴雨，天空忽然黑下来，一阵大雨把天空和世界洗得干干净净，空气变得格外清新。","Zuì nánwàng de shì xiàjì de bàoyǔ, tiānkōng hūrán hēi xiàlai, yí zhèn dàyǔ bǎ tiānkōng hé shìjiè xǐ de gāngān-jìngjìng, kōngqì biàn de géwài qīngxīn.","Khó quên nhất là cơn mưa rào mùa hè: bầu trời bỗng tối sầm lại, một trận mưa lớn rửa sạch bầu trời và cả thế giới, không khí trở nên đặc biệt trong lành."],["夏","我特别喜欢看雨后的红墙和绿瓦，喜欢雨后到北海公园划小船。","Wǒ tèbié xǐhuan kàn yǔ hòu de hóng qiáng hé lǜ wǎ, xǐhuan yǔ hòu dào Běihǎi Gōngyuán huá xiǎo chuán.","Tôi đặc biệt thích ngắm tường đỏ ngói xanh sau mưa, thích sau mưa đến công viên Bắc Hải chèo thuyền nhỏ."],["夏","到北海要经过文津街。文津街是北京城里我最喜爱的一条路，走过那里，就会想起历史。","Dào Běihǎi yào jīngguò Wénjīn Jiē. Wénjīn Jiē shì Běijīng chéng lǐ wǒ zuì xǐ’ài de yì tiáo lù, zǒuguò nàlǐ, jiù huì xiǎngqǐ lìshǐ.","Đến Bắc Hải phải đi qua phố Văn Tân. Phố Văn Tân là con đường tôi yêu thích nhất trong thành Bắc Kinh, đi qua đó là lại nhớ đến lịch sử."],["秋","北京的春天很短，可是秋天却很长。从树叶变黄，到水面结冰，都属于秋季。","Běijīng de chūntiān hěn duǎn, kěshì qiūtiān què hěn cháng. Cóng shùyè biàn huáng, dào shuǐmiàn jié bīng, dōu shǔyú qiūjì.","Mùa xuân Bắc Kinh rất ngắn, nhưng mùa thu lại rất dài. Từ lúc lá cây úa vàng đến khi mặt nước đóng băng đều thuộc về mùa thu."],["秋","秋的第一个消息，就是水果上市。就拿水果的种类来说吧，那真是太多了：枣、葡萄、梨……都是秋季的水果。","Qiū de dì-yī ge xiāoxi, jiù shì shuǐguǒ shàngshì. Jiù ná shuǐguǒ de zhǒnglèi lái shuō ba, nà zhēn shì tài duō le: zǎo, pútao, lí…… dōu shì qiūjì de shuǐguǒ.","Tin đầu tiên của mùa thu là trái cây ra chợ. Cứ lấy chủng loại trái cây mà nói, thật là quá nhiều: táo tàu, nho, lê… đều là trái cây mùa thu."],["秋","西来顺门前，假如摆出那两面大招牌——一面招牌上写着“涮”，一面招牌上写着“烤”，那就是告诉人们，秋天来了。","Xīláishùn ménqián, jiǎrú bǎi chū nà liǎng miàn dà zhāopai——yí miàn zhāopai shang xiězhe “shuàn”, yí miàn zhāopai shang xiězhe “kǎo”, nà jiù shì gàosu rénmen, qiūtiān lái le.","Trước cửa quán Tây Lai Thuận, nếu bày ra hai tấm biển lớn — một tấm viết “涮” (nhúng lẩu), một tấm viết “烤” (nướng) — thì có nghĩa là mùa thu đã đến."],["秋","从人来人往的西单向南，一路上都能闻到烤肉香。","Cóng rén lái rén wǎng de Xīdān xiàng nán, yílù shang dōu néng wéndào kǎoròu xiāng.","Từ Tây Đơn tấp nập người qua lại đi về phía nam, suốt dọc đường đều ngửi thấy mùi thịt nướng thơm."],["秋","从那时起，一天不知要从外地运来多少只羊，才能满足北京人的馋嘴呢！","Cóng nà shí qǐ, yì tiān bù zhī yào cóng wàidì yùnlái duōshao zhī yáng, cái néng mǎnzú Běijīng rén de chánzuǐ ne!","Từ lúc ấy, mỗi ngày không biết phải chở từ nơi khác đến bao nhiêu con cừu mới thỏa được cái miệng thèm ăn của người Bắc Kinh!"],["秋","每年的秋天，都要有几次郊游。最先去寻找秋天的人，大部分是青年学生，他们带来西山红叶已经红透的消息，于是去西山的路上都是去看红叶的人。","Měi nián de qiūtiān, dōu yào yǒu jǐ cì jiāoyóu. Zuì xiān qù xúnzhǎo qiūtiān de rén, dà bùfen shì qīngnián xuésheng, tāmen dàilái Xīshān hóngyè yǐjīng hóng tòu de xiāoxi, yúshì qù Xīshān de lù shang dōu shì qù kàn hóngyè de rén.","Mỗi mùa thu đều có vài lần đi dã ngoại. Những người đi tìm mùa thu sớm nhất phần lớn là học sinh, sinh viên trẻ; họ mang về tin lá đỏ Tây Sơn đã đỏ rực, thế là trên đường đến Tây Sơn toàn là người đi ngắm lá đỏ."],["秋","带几片红叶回来，夹在书里，好像成了北京人的习惯。","Dài jǐ piàn hóngyè huílai, jiā zài shū lǐ, hǎoxiàng chéng le Běijīng rén de xíguàn.","Mang về vài chiếc lá đỏ, kẹp vào sách, dường như đã thành thói quen của người Bắc Kinh."],["秋","秋深了，冬天快到了，年轻人从床底下拿出休息了一年的冰鞋，把它擦得亮亮的，等着北海结冰。","Qiū shēn le, dōngtiān kuài dào le, niánqīng rén cóng chuáng dǐxia ná chū xiūxi le yì nián de bīngxié, bǎ tā cā de liàngliàng de, děngzhe Běihǎi jié bīng.","Thu đã sâu, đông sắp đến, các bạn trẻ lôi từ gầm giường ra đôi giày trượt băng đã nghỉ cả năm, lau cho sáng bóng, chờ hồ Bắc Hải đóng băng."],["冬","现在，应该正是北京的初冬，窗外也许正下着大雪，在温暖的屋子里吃着像梨一样甜的“心儿里美”，真可口。","Xiànzài, yīnggāi zhèng shì Běijīng de chūdōng, chuāng wài yěxǔ zhèng xiàzhe dà xuě, zài wēnnuǎn de wūzi lǐ chīzhe xiàng lí yíyàng tián de “xīn’erlǐměi”, zhēn kěkǒu.","Giờ này hẳn là đầu đông ở Bắc Kinh, ngoài cửa sổ có lẽ đang đổ tuyết lớn; trong căn phòng ấm áp ăn củ “tâm nhi lý mỹ” ngọt như quả lê, thật ngon miệng."],["冬","北京人管一种绿皮红心儿的萝卜叫“心儿里美”。","Běijīng rén guǎn yì zhǒng lǜ pí hóng xīnr de luóbo jiào “xīn’erlǐměi”.","Người Bắc Kinh gọi một loại củ cải vỏ xanh ruột đỏ là “tâm nhi lý mỹ”."],["冬","离开北京的那年，正是秋叶红了的时候，但是冰鞋还来不及拿出来，我就离开了她。","Líkāi Běijīng de nà nián, zhèng shì qiū yè hóng le de shíhou, dànshì bīngxié hái láibují ná chūlai, wǒ jiù líkāi le tā.","Năm rời Bắc Kinh, đúng lúc lá thu đỏ, nhưng đôi giày trượt băng còn chưa kịp lấy ra thì tôi đã rời xa thành phố ấy."],["冬","飞机在北京的上空绕了一圈，协和医院的绿瓦是我难忘的最后一眼，我的心在流泪，那是一种离开母亲的感觉。","Fēijī zài Běijīng de shàngkōng rào le yì quān, Xiéhé Yīyuàn de lǜ wǎ shì wǒ nánwàng de zuìhòu yì yǎn, wǒ de xīn zài liú lèi, nà shì yì zhǒng líkāi mǔqin de gǎnjué.","Máy bay lượn một vòng trên bầu trời Bắc Kinh, mái ngói xanh của bệnh viện Hiệp Hòa là cái nhìn cuối cùng khó quên của tôi; lòng tôi rơi lệ, đó là cảm giác rời xa mẹ."]]}]},{"n":2,"ten":"租房只要一个条件","doan":[{"t":"课文","c":[["","一位刚从外地来的朋友让我帮她在市区租套房子。","Yí wèi gāng cóng wàidì lái de péngyou ràng wǒ bāng tā zài shìqū zū tào fángzi.","Một người bạn vừa từ nơi khác đến nhờ tôi giúp cô ấy thuê một căn nhà trong khu nội thành."],["","一个同事向我推荐了一套住房。","Yí ge tóngshì xiàng wǒ tuījiàn le yí tào zhùfáng.","Một đồng nghiệp giới thiệu cho tôi một căn nhà."],["","虽然是老房子，但是，周边的配套设施很齐全：不到两百米，就有一家大型超市，生活很方便；","Suīrán shì lǎo fángzi, dànshì, zhōubiān de pèitào shèshī hěn qíquán: bú dào liǎng bǎi mǐ, jiù yǒu yì jiā dàxíng chāoshì, shēnghuó hěn fāngbiàn;","Tuy là nhà cũ nhưng các tiện ích xung quanh rất đầy đủ: chưa đến hai trăm mét đã có một siêu thị lớn, sinh hoạt rất thuận tiện;"],["","附近就有一家大医院，谁没有生病的时候啊？离医院近点儿，就不担心了；","Fùjìn jiù yǒu yì jiā dà yīyuàn, shéi méiyǒu shēngbìng de shíhou a? Lí yīyuàn jìn diǎnr, jiù bù dānxīn le;","gần đó có một bệnh viện lớn — ai mà chẳng có lúc ốm? Ở gần bệnh viện một chút thì không phải lo nữa;"],["","往东走五分钟就是农贸市场，想吃什么就买什么，都是新鲜的。","Wǎng dōng zǒu wǔ fēnzhōng jiù shì nóngmào shìchǎng, xiǎng chī shénme jiù mǎi shénme, dōu shì xīnxiān de.","đi về phía đông năm phút là chợ nông sản, muốn ăn gì mua nấy, thứ nào cũng tươi."],["","另一位大学同学也向我推荐了一套房子。他说，那是一套新房，装修以后就没怎么1住过。","Lìng yí wèi dàxué tóngxué yě xiàng wǒ tuījiàn le yí tào fángzi. Tā shuō, nà shì yí tào xīnfáng, zhuāngxiū yǐhòu jiù méi zěnme zhù guo.","Một bạn đại học khác cũng giới thiệu cho tôi một căn nhà. Bạn ấy nói đó là nhà mới, sửa sang xong gần như chưa ai ở."],["","听说租房的是位女性，我的同学还热情地说：“那就更合适了，小区外边就有两家女子美容院、一家健身房、三家咖啡厅，离小区一百多米，就是一家五星级酒店。”","Tīngshuō zūfáng de shì wèi nǚxìng, wǒ de tóngxué hái rèqíng de shuō: “Nà jiù gèng héshì le, xiǎoqū wàibian jiù yǒu liǎng jiā nǚzǐ měiróngyuàn, yì jiā jiànshēnfáng, sān jiā kāfēitīng, lí xiǎoqū yìbǎi duō mǐ, jiù shì yì jiā wǔ xīngjí jiǔdiàn.”","Nghe nói người thuê là phụ nữ, bạn tôi nhiệt tình nói: “Vậy càng hợp, ngay ngoài khu có hai thẩm mỹ viện nữ, một phòng tập, ba quán cà phê, cách khu hơn một trăm mét còn có một khách sạn năm sao.”"],["","同学还骄傲地说：“住在那个小区的人，都是有钱、有地位的人，你那位朋友住进去，一定会感觉生活档次提高了。”","Tóngxué hái jiāo'ào de shuō: “Zhù zài nà ge xiǎoqū de rén, dōu shì yǒu qián, yǒu dìwèi de rén, nǐ nà wèi péngyou zhù jìnqu, yídìng huì gǎnjué shēnghuó dàngcì tígāo le.”","Bạn còn tự hào nói: “Người sống trong khu đó đều là người có tiền, có địa vị; bạn của cậu dọn vào chắc chắn sẽ thấy đẳng cấp cuộc sống nâng lên.”"],["","我又去房屋中介公司，打听到几套房子。","Wǒ yòu qù fángwū zhōngjiè gōngsī, dǎting dào jǐ tào fángzi.","Tôi lại đến công ty môi giới nhà đất, hỏi được vài căn."],["","一套房子是学区房，小孩子上学方便。我知道朋友的孩子已经上学了，对她来说，孩子上学是件大事，这房子可以考虑。","Yí tào fángzi shì xuéqū fáng, xiǎo háizi shàngxué fāngbiàn. Wǒ zhīdào péngyou de háizi yǐjīng shàngxué le, duì tā lái shuō, háizi shàngxué shì jiàn dàshì, zhè fángzi kěyǐ kǎolǜ.","Một căn là nhà khu trường học, trẻ con đi học thuận tiện. Tôi biết con bạn đã đi học, với cô ấy việc con đi học là chuyện lớn, căn này có thể cân nhắc."],["","另一套房子是湖景房，从家里推开窗户，可以远远地看见湖面。可2别小看了这一点，在我们这个城市，能看见湖景的房子，可不多。","Lìng yí tào fángzi shì hújǐng fáng, cóng jiā lǐ tuīkāi chuānghu, kěyǐ yuǎnyuǎn de kànjiàn húmiàn. Kě bié xiǎokàn le zhè yì diǎn, zài wǒmen zhè ge chéngshì, néng kànjiàn hújǐng de fángzi, kě bù duō.","Căn khác là nhà view hồ, đẩy cửa sổ ra có thể nhìn thấy mặt hồ ở xa. Đừng coi thường điểm này, ở thành phố chúng tôi nhà nhìn thấy hồ không nhiều đâu."],["","从家里走到湖边去散散步，该是多么浪漫的事情啊！这房子真不错。","Cóng jiā lǐ zǒu dào húbiān qù sànsan bù, gāi shì duōme làngmàn de shìqing a! Zhè fángzi zhēn búcuò.","Từ nhà đi bộ ra bờ hồ dạo một chút, thật là lãng mạn biết bao! Căn này thật không tồi."],["","还有一套房子，虽然周边没什么特殊的配套设施，但是，从地点来看，离朋友上班的地方很近，步行十几分钟就能够到公司。我的朋友又不会开车，这房子是再合适不过了。","Hái yǒu yí tào fángzi, suīrán zhōubiān méi shénme tèshū de pèitào shèshī, dànshì, cóng dìdiǎn lái kàn, lí péngyou shàngbān de dìfang hěn jìn, bùxíng shí jǐ fēnzhōng jiù néng gòu dào gōngsī. Wǒ de péngyou yòu bú huì kāichē, zhè fángzi shì zài héshì bú guò le.","Còn một căn nữa, tuy xung quanh không có tiện ích gì đặc biệt, nhưng xét về vị trí thì rất gần chỗ bạn đi làm, đi bộ hơn mười phút là tới công ty. Bạn tôi lại không biết lái xe, căn này thì không gì hợp hơn."],["","当我向朋友一一3介绍这几套房子的时候，她忽然问我：“有没有哪个房子附近有书店，或者图书馆？”","Dāng wǒ xiàng péngyou yīyī jièshào zhè jǐ tào fángzi de shíhou, tā hūrán wèn wǒ: “Yǒu méiyǒu nǎ ge fángzi fùjìn yǒu shūdiàn, huòzhě túshūguǎn?”","Khi tôi lần lượt giới thiệu mấy căn nhà cho bạn, cô ấy chợt hỏi: “Có căn nào gần đó có hiệu sách hoặc thư viện không?”"],["","书店？图书馆？什么意思啊？","Shūdiàn? Túshūguǎn? Shénme yìsi a?","Hiệu sách? Thư viện? Nghĩa là sao nhỉ?"],["","朋友说：“离农贸市场远点儿，多走几步路就行了；房子旧点儿，家具少点儿，也没有关系；况且，我很少逛商店超市，更没有时间去美容健身，这些配套设施对我没什么用。可是，附近一定要有一家大一点儿的书店，或者图书馆。”","Péngyou shuō: “Lí nóngmào shìchǎng yuǎn diǎnr, duō zǒu jǐ bù lù jiù xíng le; fángzi jiù diǎnr, jiājù shǎo diǎnr, yě méiyǒu guānxi; kuàngqiě, wǒ hěn shǎo guàng shāngdiàn chāoshì, gèng méiyǒu shíjiān qù měiróng jiànshēn, zhèxiē pèitào shèshī duì wǒ méi shénme yòng. Kěshì, fùjìn yídìng yào yǒu yì jiā dà yìdiǎnr de shūdiàn, huòzhě túshūguǎn.”","Bạn nói: “Cách chợ nông sản xa một chút, đi thêm vài bước là được; nhà cũ một chút, đồ đạc ít một chút cũng không sao; hơn nữa, tôi ít khi đi dạo cửa hàng siêu thị, càng không có thời gian đi làm đẹp tập thể hình, những tiện ích này với tôi chẳng có tác dụng gì. Nhưng gần đó nhất định phải có một hiệu sách hay thư viện lớn hơn một chút.”"],["","我吃惊地看着朋友。","Wǒ chījīng de kànzhe péngyou.","Tôi ngạc nhiên nhìn bạn."],["","朋友看出我的困惑，就解释说：“我经常要加班，不能照顾孩子，特别是寒暑假的时候，更是没办法。把他一个人放在家里，或者放在别的地方，我都不放心，所以，我常常把孩子送到书店或者图书馆去看书。","Péngyou kànchū wǒ de kùnhuò, jiù jiěshì shuō: “Wǒ jīngcháng yào jiābān, bù néng zhàogù háizi, tèbié shì hánshǔjià de shíhou, gèng shì méi bànfǎ. Bǎ tā yí ge rén fàng zài jiā lǐ, huòzhě fàng zài bié de dìfang, wǒ dōu bú fàngxīn, suǒyǐ, wǒ chángcháng bǎ háizi sòng dào shūdiàn huòzhě túshūguǎn qù kàn shū.","Bạn nhìn ra sự băn khoăn của tôi liền giải thích: “Tôi thường phải tăng ca, không chăm được con, nhất là kỳ nghỉ đông hè thì càng hết cách. Để con ở nhà một mình hay gửi chỗ khác tôi đều không yên tâm, nên tôi thường đưa con đến hiệu sách hoặc thư viện đọc sách."],["","在我过去工作的城市，我家附近就是市图书馆，孩子每个星期都去那儿看书，他已经适应了这样的生活，所以我想找一个附近有图书馆或书店的房子。”","Zài wǒ guòqù gōngzuò de chéngshì, wǒ jiā fùjìn jiùshì shì túshūguǎn, háizi měi ge xīngqī dōu qù nàr kàn shū, tā yǐjīng shìyìng le zhèyàng de shēnghuó, suǒyǐ wǒ xiǎng zhǎo yí ge fùjìn yǒu túshūguǎn huò shūdiàn de fángzi.”","Ở thành phố tôi từng làm việc, gần nhà là thư viện thành phố, tuần nào con cũng đến đó đọc sách, nó đã quen với cuộc sống ấy, nên tôi muốn tìm căn nhà gần thư viện hoặc hiệu sách.”"],["","想一想，我也遇到过孩子没人照顾的困境，不同的是，我家附近有个超市，我经常把孩子放在超市的儿童活动区里玩儿，等我忙完事情，再去超市找他。","Xiǎng yì xiǎng, wǒ yě yùdào guo háizi méi rén zhàogù de kùnjìng, bù tóng de shì, wǒ jiā fùjìn yǒu ge chāoshì, wǒ jīngcháng bǎ háizi fàng zài chāoshì de értóng huódòngqū lǐ wánr, děng wǒ máng wán shìqing, zài qù chāoshì zhǎo tā.","Nghĩ lại, tôi cũng từng gặp cảnh con không có ai trông, khác là gần nhà tôi có siêu thị, tôi thường để con chơi ở khu hoạt động trẻ em trong siêu thị, bận xong việc rồi mới ra đón."],["","在我为朋友找的那几套房子里，还真有一套房子，附近就是省图书馆。可是，介绍房子的人，根本没有提到图书馆，也许在他看来，图书馆根本就不是什么重要的配套设施吧。","Zài wǒ wèi péngyou zhǎo de nà jǐ tào fángzi lǐ, hái zhēn yǒu yí tào fángzi, fùjìn jiùshì shěng túshūguǎn. Kěshì, jièshào fángzi de rén, gēnběn méiyǒu tídào túshūguǎn, yěxǔ zài tā kàn lái, túshūguǎn gēnběn jiù bú shì shénme zhòngyào de pèitào shèshī ba.","Trong mấy căn tôi tìm cho bạn, quả thật có một căn gần ngay thư viện tỉnh. Nhưng người giới thiệu nhà hoàn toàn không nhắc đến thư viện; có lẽ theo anh ta, thư viện chẳng phải tiện ích quan trọng gì."],["","而我的朋友却告诉我，那是比超市和美容院更重要的配套设施。","Ér wǒ de péngyou què gàosu wǒ, nà shì bǐ chāoshì hé měiróngyuàn gèng zhòngyào de pèitào shèshī.","Vậy mà bạn tôi lại nói với tôi, đó là tiện ích còn quan trọng hơn siêu thị và thẩm mỹ viện."]]}]}]}];
